const SUPABASE_ANON_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImJxcnBpb29rdWNzZGp2Y3ZqcnVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODMyNjAxOTgsImV4cCI6MjA5ODgzNjE5OH0.qfjK9-OTsRJFuywvZFWsAFsOgMWzLIvx8Fc5-xeQuqA";
const IS_CONFIGURED     = Boolean(SUPABASE_URL && SUPABASE_ANON_KEY);

// A real, deliberate architectural choice, not an oversight: IS_CONFIGURED
// is a single global flag, evaluated once, read by every one of this
// app's 90+ useCompanyTable() calls to decide whether to fetch real data
// or serve local seed data. That's correct for its original purpose —
// "does a live Supabase project exist at all" — but it has no concept of
// a person choosing to preview a demo despite real credentials being
// configured. Rather than touch every one of those 90+ call sites to add
// a second, separate check (real, but a much larger and riskier change
// for what should be a small, safe feature), this single mutable flag is
// read by the one function they all already funnel through
// (useCompanyTable's own real/seed decision), making the fix centralized
// and low-risk instead of scattered and error-prone.
let DEMO_OVERRIDE = false;

// There is deliberately no ACTIVE_COMPANY_ID constant. Company scoping is
// enforced entirely by RLS's current_company_id(), which reads the real
// authenticated session (see section 32 of the handover doc) — a single
// hardcoded constant could never correctly scope queries once real
// multi-user login exists, since different signed-in users belong to
// different companies. The client never supplies its own company filter;
// the database is the single source of truth for which rows a session can see.

function authHeaders() {
  const token = (typeof window !== "undefined" && window.localStorage?.getItem("bs_access_token")) || SUPABASE_ANON_KEY;
  return {
    apikey: SUPABASE_ANON_KEY,
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
  };
}

// Real Supabase Auth REST calls — the actual GoTrue endpoints every
// supabase-js client calls under the hood, hit directly with fetch() the
// same way sb() hits PostgREST directly. Only meaningful when IS_CONFIGURED
// (a real Supabase project is connected); LoginPage/SignupPage below
// branch on that constant and simulate the flow locally in demo mode
// rather than pretending to authenticate against a backend that isn't there.
async function authSignUp(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/signup`, {
    method: "POST",
    headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Sign up failed.");
  return data; // { access_token, refresh_token, user } once email confirmation is satisfied, or { user } if a project requires confirmation first
}

async function authSignIn(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: "POST",
    headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Incorrect email or password.");
  return data; // { access_token, refresh_token, user }
}

async function authSignOut(accessToken) {
  try {
    await fetch(`${SUPABASE_URL}/auth/v1/logout`, {
      method: "POST",
      headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${accessToken}` },
    });
  } catch (_e) { /* the local session is cleared regardless of whether the server call succeeds */ }
}

// Identifies who a stored access token actually belongs to — the real
// Supabase Auth endpoint for exactly this, used to resume a session on
// page load without re-prompting for a password every reload.
async function authGetUser(accessToken) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
    headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${accessToken}` },
  });
  if (!res.ok) throw new Error("Session expired");
  return res.json();
}

// Real OAuth sign-in — redirects the browser to Supabase's actual
// /authorize endpoint for the named provider (google, azure, or apple).
// This call itself is genuine and correct; whether it actually reaches a
// working consent screen depends entirely on that provider being enabled
// in this project's Supabase dashboard (Authentication > Providers) with
// a real OAuth client ID and secret from Google Cloud Console, Azure AD,
// or Apple's own developer portal — none of which this codebase can
// create. Google and Microsoft (Azure) both have free tiers for this;
// Apple requires a paid Apple Developer account, the one provider here
// with a real cost attached before it can be turned on at all.
function authSignInWithOAuth(provider) {
  const redirectTo = typeof window !== "undefined" ? window.location.origin + window.location.pathname : "";
  window.location.href = `${SUPABASE_URL}/auth/v1/authorize?provider=${provider}&redirect_to=${encodeURIComponent(redirectTo)}`;
}

// Calls the two SECURITY DEFINER functions added to the schema
// (create_company_and_owner, join_company_with_code) via PostgREST's RPC
// endpoint — the correct, safe way to expose a multi-step, atomic
// operation to a client without granting raw table INSERT.
async function callRpc(name, params, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/${name}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify(params),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.message || data.error_description || `${name} failed.`);
  return data;
}

// Minimal chainable query builder over PostgREST, mirroring the shape of the
// official supabase-js client closely enough that swapping later is trivial.
function sb(table) {
  let path = `${SUPABASE_URL}/rest/v1/${table}`;
  const params = new URLSearchParams();
  let method = "GET";
  let body = null;
  let single = false;

  const builder = {
    select(cols = "*") {
      params.set("select", cols);
      return builder;
    },
    eq(col, val) {
      params.append(col, `eq.${val}`);
      return builder;
    },
    order(col, { ascending = true } = {}) {
      params.set("order", `${col}.${ascending ? "asc" : "desc"}`);
      return builder;
    },
    insert(row) {
      method = "POST";
      body = JSON.stringify(row);
      return builder;
    },
    update(patch) {
      method = "PATCH";
      body = JSON.stringify(patch);
      return builder;
    },
    delete() {
      method = "DELETE";
      return builder;
    },
    single() {
      single = true;
      return builder;
    },
    async run() {
      const url = `${path}?${params.toString()}`;
      const res = await fetch(url, {
        method,
        headers: {
          ...authHeaders(),
          Prefer: method === "GET" ? undefined : "return=representation",
        },
        body,
      });
      if (!res.ok) throw new Error(`Supabase ${method} ${table} failed: ${res.status}`);
      const data = await res.json();
      return single ? data[0] : data;
    },
    // allow `await sb(table).select().eq(...)` directly, like supabase-js
    then(resolve, reject) {
      return builder.run().then(resolve, reject);
    },
  };
  return builder;
}

/* Generic hook: loads a company-scoped table when configured, otherwise
   serves the given seed array untouched. Every module's data hook below
   follows this same shape — copy it when wiring HR, Manufacturing, etc. */
function useCompanyTable(table, seed, { select = "*", order, mapRow } = {}) {
  // Demo mode serves the seed instantly. Live mode starts empty and loading —
  // flashing demo rows and then swapping them for real data reads as a glitch.
  // isLive folds in DEMO_OVERRIDE too — a person previewing the demo despite
  // real credentials being configured should see the same instant, honest
  // seed data as someone with no Supabase project connected at all, not a
  // broken screen quietly trying to fetch real data with no real session.
  const isLive = IS_CONFIGURED && !DEMO_OVERRIDE;
  const [rows, setRows] = useState(isLive ? [] : seed);
  const [loading, setLoading] = useState(isLive);
  const [error, setError] = useState(null);

  const reload = useCallback(async () => {
    if (!isLive) return;
    setLoading(true);
    setError(null);
    try {
      // Company scoping is enforced entirely by RLS's current_company_id()
      // (reading the real authenticated session — see section 32 of the
      // handover doc), not filtered again here. A hardcoded ACTIVE_COMPANY_ID
      // constant could never correctly scope queries once real multi-user
      // login exists — different signed-in users belong to different
      // companies, so the one thing that must never happen is the client
      // supplying its own company_id filter; RLS is the single source of
      // truth for which rows a given session can see.
      let q = sb(table).select(select);
      if (order) q = q.order(order.col, { ascending: order.ascending });
      const data = await q.run();
      // mapRow translates the database's snake_case/UUID-keyed shape into
      // the UI's camelCase shape (see mapRow functions below). Every mapped
      // row keeps its real UUID on `dbId` so mutation handlers can target
      // the correct database row even though the UI displays a friendlier
      // id. Tables without a mapper pass through unchanged (demo-only tables).
      setRows(mapRow ? data.map(mapRow) : data);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, [table, select, order, mapRow]);

  useEffect(() => { reload(); }, [reload]);

  return { rows, setRows, loading, error, reload };
}

/* =============================================================================
   DB → UI ROW MAPPERS
   PostgREST returns snake_case columns keyed by UUID; every UI component in
   this file expects camelCase fields keyed by a human-readable document
   number (L-0231, INV-8801, HDW-2201...). These mappers bridge that gap for
   each live-mapped table. `dbId` carries the real UUID through for mutation
   calls (`.eq("id", row.dbId ?? row.id)`); everything else matches the
   corresponding seed shape exactly, so no component code has to change.

   Coverage: crm_leads, inventory_items, finance_expenses, and the three
   sales document tables (with embedded line items via PostgREST's nested
   select). Other live tables (HR, Manufacturing, SCM, E-Commerce, Documents)
   do not yet have mappers — see the handover doc for the remaining list.
   ============================================================================= */

function mapLeadRow(r) {
  return {
    id: r.id, dbId: r.id,
    name: r.contact_name, company: r.company_name, stage: r.stage,
    value: Number(r.value_amount) || 0, currency: r.currency || "TZS000",
    owner: r.owner_id || "Unassigned", email: r.email || "", phone: r.phone || "",
    industry: r.industry || "General", score: r.score ?? 50,
    lastActivity: r.last_activity_at ? new Date(r.last_activity_at).toLocaleDateString() : "—",
    expectedCloseDate: r.expected_close_date || null,
  };
}

function mapContactRow(r) {
  return {
    id: r.id, dbId: r.id,
    name: r.name, title: r.title || "", company: r.company, email: r.email || "", phone: r.phone || "", isPrimary: r.is_primary,
  };
}

