function Training({ employees }) {
  const training = useCompanyTable("hr_training", trainingSeed, { order: { col: "id", ascending: false }, mapRow: mapTrainingRow });
  const { rows, setRows, loading } = training;
  const [showForm, setShowForm] = useState(false);

  async function addTraining(form) {
    const draft = { id: docId("TRN"), employee: form.employee, course: form.course, status: "Not Started", completionDate: null };
    setRows((prev) => [draft, ...prev]);
    setShowForm(false);
    notify(`Training assigned: ${draft.course}`);
    if (IS_CONFIGURED) {
      try { await sb("hr_training").insert({ employee_name: draft.employee, course: draft.course, status: "Not Started" }).run(); } catch (_e) { notify("Assigned locally, but saving to the server failed.", "error"); }
    }
  }

  async function advance(id) {
    const t = rows.find((x) => x.id === id);
    const next = t.status === "Not Started" ? "In Progress" : "Completed";
    const completionDate = next === "Completed" ? TODAY.toISOString().slice(0, 10) : null;
    setRows((prev) => prev.map((x) => (x.id === id ? { ...x, status: next, completionDate } : x)));
    if (IS_CONFIGURED && t?.dbId) {
      try { await sb("hr_training").eq("id", t.dbId).update({ status: next, completion_date: completionDate }).run(); } catch (_e) { notify("Couldn't save training status to the server.", "error"); }
    }
  }

  return (
    <div className="space-y-5">
      <div className="flex justify-end">
        <button onClick={() => setShowForm(true)} className="btn-primary text-white text-[13px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5 shadow-sm">
          <Plus size={15} /> Assign Training
        </button>
      </div>
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-[13px] min-w-[600px]">
            <thead><tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
              <th className="px-4 py-3 font-medium">Employee</th><th className="px-4 py-3 font-medium">Course</th><th className="px-4 py-3 font-medium">Status</th><th className="px-4 py-3 font-medium">Completed</th><th className="px-4 py-3"></th>
            </tr></thead>
            <tbody>
              {loading && <SkeletonRows cols={5} />}
              {!loading && rows.map((t) => (
                <tr key={t.id} className="border-b border-slate-50 last:border-0">
                  <td className="px-4 py-3 font-medium text-[#111827]">{t.employee}</td>
                  <td className="px-4 py-3 text-slate-500">{t.course}</td>
                  <td className="px-4 py-3">
                    <span className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5" style={{ backgroundColor: `${TRAINING_STATUS_COLOR[t.status]}14`, color: TRAINING_STATUS_COLOR[t.status] }}>
                      <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: TRAINING_STATUS_COLOR[t.status] }} />{t.status}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-slate-500 font-mono">{t.completionDate || "—"}</td>
                  <td className="px-4 py-3 text-right">
                    {t.status !== "Completed" && (
                      <button onClick={() => advance(t.id)} className="text-[11.5px] font-medium text-[#16A34A] hover:text-[#15803D]">
                        Mark {t.status === "Not Started" ? "In Progress" : "Completed"}
                      </button>
                    )}
                  </td>
                </tr>
              ))}
              {!loading && rows.length === 0 && <tr><td colSpan={5}><EmptyState icon={GraduationCap} title="No training assigned yet" hint="Courses assigned to your team will appear here." actionLabel="Assign Training" onAction={() => setShowForm(true)} /></td></tr>}
            </tbody>
          </table>
        </div>
      </div>
      {showForm && <TrainingFormPanel employees={employees} onClose={() => setShowForm(false)} onSubmit={addTraining} />}
    </div>
  );
}

