function Benefits({ employees }) {
  const benefits = useCompanyTable("hr_benefits", benefitsSeed, { order: { col: "enrollment_date", ascending: false }, mapRow: mapBenefitRow });
  const { rows, setRows, loading } = benefits;
  const [showForm, setShowForm] = useState(false);
  const totalMonthly = rows.filter((b) => b.status === "Active").reduce((s, b) => s + b.monthlyValue, 0);

  async function addBenefit(form) {
    const draft = { id: docId("BEN"), employee: form.employee, type: form.type, monthlyValue: Number(form.monthlyValue) || 0, status: "Active", enrollmentDate: TODAY.toISOString().slice(0, 10) };
    setRows((prev) => [draft, ...prev]);
    setShowForm(false);
    notify(`Enrolled ${draft.employee} in ${draft.type}`);
    if (IS_CONFIGURED) {
      try { await sb("hr_benefits").insert({ employee_name: draft.employee, benefit_type: draft.type, monthly_value: draft.monthlyValue, status: "Active", enrollment_date: draft.enrollmentDate }).run(); } catch (_e) { notify("Enrolled locally, but saving to the server failed.", "error"); }
    }
  }

  async function toggleStatus(id) {
    const b = rows.find((x) => x.id === id);
    const next = b.status === "Active" ? "Inactive" : "Active";
    setRows((prev) => prev.map((x) => (x.id === id ? { ...x, status: next } : x)));
    if (IS_CONFIGURED && b?.dbId) {
      try { await sb("hr_benefits").eq("id", b.dbId).update({ status: next }).run(); } catch (_e) { notify("Couldn't save benefit status to the server.", "error"); }
    }
  }

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between gap-3">
        <p className="text-[13px] text-slate-500"><span className="font-mono font-semibold text-[#111827]">TZS {money(totalMonthly)}k</span>/month in active benefits</p>
        <button onClick={() => setShowForm(true)} className="btn-primary text-white text-[13px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5 shadow-sm">
          <Plus size={15} /> Enroll Benefit
        </button>
      </div>
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-[13px] min-w-[600px]">
            <thead><tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
              <th className="px-4 py-3 font-medium">Employee</th><th className="px-4 py-3 font-medium">Benefit</th><th className="px-4 py-3 font-medium text-right">Monthly (TZS 000)</th><th className="px-4 py-3 font-medium">Status</th><th className="px-4 py-3"></th>
            </tr></thead>
            <tbody>
              {loading && <SkeletonRows cols={5} />}
              {!loading && rows.map((b) => (
                <tr key={b.id} className="border-b border-slate-50 last:border-0">
                  <td className="px-4 py-3 font-medium text-[#111827]">{b.employee}</td>
                  <td className="px-4 py-3 text-slate-500">{b.type}</td>
                  <td className="px-4 py-3 text-right font-mono">{money(b.monthlyValue)}</td>
                  <td className="px-4 py-3">
                    <span className={`text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5`} style={{ backgroundColor: b.status === "Active" ? "#16A34A14" : "#9CA3AF14", color: b.status === "Active" ? "#16A34A" : "#9CA3AF" }}>
                      <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: b.status === "Active" ? "#16A34A" : "#9CA3AF" }} />{b.status}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right">
                    <button onClick={() => toggleStatus(b.id)} className="text-[11.5px] font-medium text-[#16A34A] hover:text-[#15803D]">
                      {b.status === "Active" ? "Deactivate" : "Reactivate"}
                    </button>
                  </td>
                </tr>
              ))}
              {!loading && rows.length === 0 && <tr><td colSpan={5}><EmptyState icon={HeartHandshake} title="No benefits enrolled yet" hint="Health insurance, pension, and allowances will appear here." actionLabel="Enroll Benefit" onAction={() => setShowForm(true)} /></td></tr>}
            </tbody>
          </table>
        </div>
      </div>
      {showForm && <BenefitFormPanel employees={employees} onClose={() => setShowForm(false)} onSubmit={addBenefit} />}
    </div>
  );
}

