      {tab === "banking" && <BankStatementImport invoices={invoices} expenses={expenses} />}
      {tab === "tax" && <TaxIntegration onNavigate={onNavigate} />}
      {tab === "qr-barcode" && <QRBarcodeTools onNavigate={onNavigate} />}
      {tab === "esignature" && <ESignature />}
