// Tool contract exposed to the model. Deliberately scoped to shared tables
// the assistant already reads — no tool touches data it can't see. Each
// persona above only offers the subset relevant to its role.
const AI_TOOLS_ALL = [
  {
    name: "create_lead",
    description: "Create a new sales lead in the CRM pipeline at the 'New' stage. Use when the owner asks to add a lead, prospect, or potential customer.",
    input_schema: {
      type: "object",
      properties: {
        contact_name: { type: "string", description: "Full name of the contact person" },
        company_name: { type: "string", description: "Name of the prospect's company" },
        value_tzs_k: { type: "number", description: "Estimated deal value in thousands of TZS (0 if unknown)" },
        industry: { type: "string", description: "Prospect's industry" },
        email: { type: "string" },
        phone: { type: "string" },
      },
      required: ["contact_name", "company_name"],
    },
  },
  {
    name: "adjust_stock",
    description: "Adjust the on-hand quantity of an inventory item by a signed delta (positive = restock, negative = remove). Use the exact SKU from the business snapshot.",
    input_schema: {
      type: "object",
      properties: {
        sku: { type: "string", description: "Exact SKU from the inventory snapshot, e.g. HDW-2204" },
        delta: { type: "number", description: "Signed quantity change; positive adds stock, negative removes" },
        reason: { type: "string", description: "Short reason for the adjustment" },
      },
      required: ["sku", "delta"],
    },
  },
  {
    name: "mark_invoice_paid",
    description: "Mark an outstanding invoice as fully paid, settling its balance. Use the exact invoice ID from the business snapshot.",
    input_schema: {
      type: "object",
      properties: {
        invoice_id: { type: "string", description: "Exact invoice ID from the snapshot, e.g. INV-8798" },
      },
      required: ["invoice_id"],
    },
  },
  {
    name: "record_expense",
    description: "Record a new business expense. Use when the owner describes a cost that needs to be logged.",
    input_schema: {
      type: "object",
      properties: {
        vendor: { type: "string", description: "Who the expense was paid to" },
        category: { type: "string", description: "Expense category, e.g. Supplies, Rent & Utilities, Marketing" },
        amount_tzs_k: { type: "number", description: "Amount in thousands of TZS" },
        method: { type: "string", description: "Payment method: Cash, Card, Mobile Money, or Bank Transfer" },
      },
      required: ["vendor", "category", "amount_tzs_k"],
    },
  },
  {
    name: "approve_leave",
    description: "Approve a pending leave request. Use the exact employee name and leave type from the snapshot.",
    input_schema: {
      type: "object",
      properties: {
        employee: { type: "string", description: "Exact employee name from the leave_requests snapshot" },
        type: { type: "string", description: "Leave type from the snapshot, e.g. Annual, Sick, Unpaid — disambiguates if an employee has more than one pending request" },
      },
      required: ["employee"],
    },
  },
  {
    name: "create_invoice",
    description: "Create a new invoice for a customer with one or more line items. Use exact SKUs from the inventory snapshot for pricing; if the owner names an item without a SKU, match it by name from the snapshot.",
    input_schema: {
      type: "object",
      properties: {
        customer: { type: "string", description: "Customer or company name to bill" },
        items: {
          type: "array",
          description: "Line items to bill",
          items: {
            type: "object",
            properties: {
              sku: { type: "string", description: "Exact SKU from the inventory snapshot" },
              qty: { type: "number", description: "Quantity" },
            },
            required: ["sku", "qty"],
          },
        },
        due_in_days: { type: "number", description: "Payment terms in days from today; defaults to 14 if not specified" },
      },
      required: ["customer", "items"],
    },
  },
  {
    name: "create_quotation",
    description: "Draft a new price quotation for a prospect or customer, before any commitment to buy. Use exact SKUs from the inventory snapshot for pricing.",
    input_schema: {
      type: "object",
      properties: {
        customer: { type: "string", description: "Customer or prospect name" },
        items: {
          type: "array",
          description: "Line items to quote",
          items: {
            type: "object",
            properties: {
              sku: { type: "string", description: "Exact SKU from the inventory snapshot" },
              qty: { type: "number", description: "Quantity" },
            },
            required: ["sku", "qty"],
          },
        },
        valid_days: { type: "number", description: "How many days the quote stays valid; defaults to 14" },
      },
      required: ["customer", "items"],
    },
  },
  {
    name: "create_workflow",
    description: "Set up a recurring automated workflow: generate a specific business report on a schedule, in a chosen format. This is the closest real automation this system supports — it does not create arbitrary if-this-then-that rules.",
    input_schema: {
      type: "object",
      properties: {
        report_type: { type: "string", description: "One of: Sales & Revenue, Inventory Valuation, Profit & Loss" },
        frequency: { type: "string", description: "One of: Daily, Weekly, Monthly" },
        format: { type: "string", description: "One of: CSV, Excel, PDF, Word" },
        recipient_email: { type: "string", description: "Who should receive it (informational — see the tool's own caveat about delivery not being automatic yet)" },
      },
      required: ["report_type", "frequency", "format"],
    },
  },
  {
    name: "show_chart",
    description: "Render a real chart alongside your written answer, built from the exact data you're citing. Use whenever a comparison, breakdown, or trend would be clearer as a chart than as prose — e.g. revenue by customer, expenses by category, pipeline by stage, stock value by category.",
    input_schema: {
      type: "object",
      properties: {
        title: { type: "string", description: "Chart title" },
        chart_type: { type: "string", description: "'bar' or 'line'" },
        data: {
          type: "array",
          description: "Data points to plot, using values already present in the business snapshot — never invented numbers",
          items: {
            type: "object",
            properties: {
              label: { type: "string", description: "Category or period label for this point" },
              value: { type: "number", description: "The value in thousands of TZS or count, matching what's being charted" },
            },
            required: ["label", "value"],
          },
        },
      },
      required: ["title", "chart_type", "data"],
    },
  },
];

function actionLabel(name, input) {
  if (name === "create_lead") return `Created lead: ${input.company_name}`;
  if (name === "adjust_stock") return `Adjusted ${input.sku} by ${input.delta > 0 ? "+" : ""}${input.delta}`;
  if (name === "mark_invoice_paid") return `Marked ${input.invoice_id} as paid`;
  if (name === "record_expense") return `Recorded expense: ${input.vendor} — TZS ${input.amount_tzs_k}k`;
  if (name === "approve_leave") return `Approved leave for ${input.employee}`;
  if (name === "create_invoice") return `Created invoice for ${input.customer}`;
  if (name === "create_quotation") return `Created quotation for ${input.customer}`;
  if (name === "create_workflow") return `Scheduled ${input.report_type} (${input.frequency}, ${input.format})`;
  return name;
}

function AIAssistant({ company, invoices, inventory, crm, expenses, employees, leaveRequests, suppliers, quotations, scheduledWorkflows }) {
  const [personaId, setPersonaId] = useState(null);
  const persona = AI_PERSONAS.find((p) => p.id === personaId);
  const data = { company, invoices, inventory, crm, expenses, employees, leaveRequests, suppliers, quotations, scheduledWorkflows };

  if (!persona) {
    return (
      <div className="max-w-4xl mx-auto space-y-5">
        <div>
          <h1 className="text-[20px] sm:text-[22px] font-semibold text-[#111827] tracking-tight">Smart Manager AI</h1>
          <p className="text-[13px] text-slate-500 mt-1">One assistant, twelve roles — each grounded in the live data relevant to it</p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {AI_PERSONAS.map((p) => {
            const Icon = p.icon;
            return (
              <button
                key={p.id}
                onClick={() => setPersonaId(p.id)}
                className="text-left bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5 hover:border-[#16A34A]/50 hover:shadow-md hover:-translate-y-0.5 transition-all"
              >
                <div className="w-10 h-10 rounded-lg flex items-center justify-center mb-3" style={{ background: `linear-gradient(135deg, ${p.color}, #111827)` }}>
                  <Icon size={18} className="text-white" />
                </div>
                <p className="text-[14px] font-semibold text-[#111827] mb-1">{p.name}</p>
                <p className="text-[12px] text-slate-500 leading-relaxed">{p.tagline}</p>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full min-h-[75vh] max-w-3xl mx-auto">
      <div className="mb-4 flex items-start justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg flex items-center justify-center shrink-0" style={{ background: `linear-gradient(135deg, ${persona.color}, #111827)` }}>
            <persona.icon size={18} className="text-white" />
          </div>
          <div>
            <h1 className="text-[18px] sm:text-[20px] font-semibold text-[#111827] tracking-tight">{persona.name}</h1>
            <p className="text-[12.5px] text-slate-500">{persona.tagline}</p>
          </div>
        </div>
        <button onClick={() => setPersonaId(null)} className="btn-secondary text-[12px] font-medium rounded-lg px-3 py-1.5 shrink-0">
          Switch Assistant
        </button>
      </div>

      {persona.disclaimer && (
        <div className="flex items-start gap-2.5 bg-[#F59E0B]/5 border border-[#F59E0B]/20 rounded-lg p-3 mb-4">
          <AlertCircle size={15} className="text-[#F59E0B] shrink-0 mt-0.5" />
          <p className="text-[12px] text-[#8a670a] leading-relaxed">{persona.disclaimer}</p>
        </div>
      )}

      {persona.mode === "docgen" && <DocumentGenerator company={company} />}
      {persona.mode === "meeting" && <AIMeetingAssistant company={company} />}
      {persona.mode !== "docgen" && persona.mode !== "meeting" && <ChatInterface persona={persona} data={data} />}
    </div>
  );
}

/* -------------------------------- AI CHAT ENGINE -------------------------------- */

// The one real chat engine every conversational persona shares. Scoped
// per-call by `persona`: which data it sees, which tools it may use, how
// it introduces itself. Nothing here is persona-specific logic — that all
// lives in the AI_PERSONAS config above.
function ChatInterface({ persona, data }) {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [listening, setListening] = useState(false);
  const recognitionRef = useRef(null);
  const speechSupported = typeof window !== "undefined" && !!(window.SpeechRecognition || window.webkitSpeechRecognition);

  const tools = AI_TOOLS_ALL.filter((t) => persona.tools.includes(t.name));

  async function executeTool(name, toolInput) {
    try {
      if (name === "create_lead") {
        const draft = {
          id: docId("L"), name: toolInput.contact_name, company: toolInput.company_name,
          stage: "New", value: Number(toolInput.value_tzs_k) || 0, currency: "TZS000", owner: `AI ${persona.name}`,
          email: toolInput.email || "", phone: toolInput.phone || "", industry: toolInput.industry || "General",
          lastActivity: "Just now", score: 50,
        };
        data.crm.setRows((prev) => [draft, ...prev]);
        notify(`Lead created: ${draft.company}`);
        if (IS_CONFIGURED) {
          try {
            const header = await sb("crm_leads").insert({
              contact_name: draft.name, company_name: draft.company, stage: "New",
              value_amount: draft.value, email: draft.email, phone: draft.phone, industry: draft.industry,
            }).single().run();
            if (header?.id) data.crm.setRows((prev) => prev.map((l) => (l.id === draft.id ? { ...l, dbId: header.id } : l)));
          } catch (_e) { notify("Lead created locally, but saving to the server failed.", "error"); }
        }
        return `Success: created lead ${draft.id} for ${draft.company} at the New stage with value TZS ${draft.value}k.`;
      }

      if (name === "adjust_stock") {
        const item = data.inventory.rows.find((it) => it.sku === toolInput.sku);
        if (!item) return `Error: no inventory item with SKU ${toolInput.sku}. Check the snapshot for valid SKUs.`;
        const delta = Number(toolInput.delta) || 0;
        const newQty = Math.max(0, item.qty + delta);
        data.inventory.setRows((prev) => prev.map((it) => (it.sku === item.sku ? { ...it, qty: newQty } : it)));
        notify(`Stock adjusted: ${item.name} ${delta > 0 ? "+" : ""}${delta}`);
        logAudit("Stock adjusted via AI Assistant", "Inventory", `AI ${persona.name}`, `${item.name} (${item.sku}) ${delta > 0 ? "+" : ""}${delta} → ${newQty} ${item.unit}`);
        if (IS_CONFIGURED) {
          try {
            await sb("inventory_items").eq("sku", item.sku).update({ qty_on_hand: newQty }).run();
            await sb("inventory_stock_movements").insert({
              item_id: item.sku, movement: delta > 0 ? "In" : "Out", qty: Math.abs(delta),
              reference: toolInput.reason || `AI ${persona.name} adjustment`,
            }).run();
          } catch (_e) { notify("Adjustment saved locally, but the server update failed.", "error"); }
        }
        return `Success: ${item.name} (${item.sku}) adjusted by ${delta}; new on-hand quantity is ${newQty} ${item.unit}.`;
      }

      if (name === "mark_invoice_paid") {
        const inv = data.invoices.rows.find((i) => i.id === toolInput.invoice_id);
        if (!inv) return `Error: no invoice with ID ${toolInput.invoice_id}. Check the snapshot for valid invoice IDs.`;
        if (inv.status === "Paid") return `No change: ${inv.id} is already fully paid.`;
        const total = lineTotal(inv.items).total;
        data.invoices.setRows((prev) => prev.map((i) => (i.id === inv.id ? { ...i, status: "Paid", amountPaid: total } : i)));
        notify(`${inv.id} marked as paid`);
        if (IS_CONFIGURED && inv.dbId) {
          try { await sb("sales_invoices").eq("id", inv.dbId).update({ status: "Paid", amount_paid: total }).run(); } catch (_e) { notify("Payment saved locally, but the server update failed.", "error"); }
        }
        return `Success: ${inv.id} for ${inv.customer} marked as Paid; TZS ${money(total)}k settled.`;
      }

      if (name === "record_expense") {
        const draft = {
          id: docId("EX"), vendor: toolInput.vendor, category: toolInput.category || "Supplies",
          date: TODAY.toISOString().slice(0, 10), dueDate: TODAY.toISOString().slice(0, 10),
          amount: Number(toolInput.amount_tzs_k) || 0, status: "Paid", method: toolInput.method || "Cash",
        };
        data.expenses.setRows((prev) => [draft, ...prev]);
        notify(`Expense recorded: ${draft.vendor}`);
        if (IS_CONFIGURED) {
          try {
            const header = await sb("finance_expenses").insert({
              vendor: draft.vendor, category: draft.category, expense_date: draft.date, due_date: draft.dueDate,
              amount: draft.amount, status: "Paid", method: draft.method,
            }).single().run();
            if (header?.id) data.expenses.setRows((prev) => prev.map((e) => (e.id === draft.id ? { ...e, dbId: header.id } : e)));
          } catch (_e) { notify("Expense recorded locally, but saving to the server failed.", "error"); }
        }
        return `Success: recorded TZS ${draft.amount}k expense to ${draft.vendor} (${draft.category}), marked Paid via ${draft.method}.`;
      }

      if (name === "approve_leave") {
        const candidates = data.leaveRequests.rows.filter((l) => l.employee === toolInput.employee && l.status === "Pending" && (!toolInput.type || l.type === toolInput.type));
        if (candidates.length === 0) return "Error: no pending leave request found for " + toolInput.employee + (toolInput.type ? " (" + toolInput.type + ")" : "") + ". Check the snapshot.";
        const target = candidates[0];
        data.leaveRequests.setRows((prev) => prev.map((l) => (l.id === target.id ? { ...l, status: "Approved" } : l)));
        notify(`Leave approved for ${target.employee}`);
        logAudit("Leave approved via AI Assistant", "HR", `AI ${persona.name}`, `${target.employee} — ${target.type}, ${target.startDate} to ${target.endDate}`);
        if (IS_CONFIGURED && target.dbId) {
          try { await sb("hr_leave_requests").eq("id", target.dbId).update({ status: "Approved" }).run(); } catch (_e) { notify("Approved locally, but the server update failed.", "error"); }
        }
        return `Success: approved ${target.type} leave for ${target.employee}, ${target.startDate} to ${target.endDate}.`;
      }

      if (name === "create_invoice" || name === "create_quotation") {
        const isInvoice = name === "create_invoice";
        const lineItems = (toolInput.items || []).map((li) => {
          const invItem = data.inventory.rows.find((it) => it.sku === li.sku);
          if (!invItem) return null;
          return { sku: invItem.sku, name: invItem.name, qty: Number(li.qty) || 1, rate: invItem.unitCost };
        }).filter(Boolean);
        if (lineItems.length === 0) return `Error: none of the requested SKUs were found in the inventory snapshot. Check the exact SKUs and try again.`;

        const docId = isInvoice ? `INV-${Math.floor(8000 + Math.random() * 1900)}` : `QT-${Math.floor(1000 + Math.random() * 900)}`;
        const orderDate = TODAY.toISOString().slice(0, 10);
        const draft = isInvoice
          ? { id: docId, customer: toolInput.customer, date: orderDate, dueDate: new Date(TODAY.getTime() + (Number(toolInput.due_in_days) || 14) * 86400000).toISOString().slice(0, 10), orderRef: "—", status: "Unpaid", amountPaid: 0, items: lineItems, payments: [] }
          : { id: docId, customer: toolInput.customer, date: orderDate, validUntil: new Date(TODAY.getTime() + (Number(toolInput.valid_days) || 14) * 86400000).toISOString().slice(0, 10), status: "Draft", owner: `AI ${persona.name}`, items: lineItems };

        const hook = isInvoice ? data.invoices : data.quotations;
        hook.setRows((prev) => [draft, ...prev]);
        const { total } = lineTotal(lineItems);
        notify(`${isInvoice ? "Invoice" : "Quotation"} ${docId} created for ${toolInput.customer} — TZS ${money(Math.round(total))}k`);
        logAudit(`${isInvoice ? "Invoice" : "Quotation"} created via AI Assistant`, "Sales", `AI ${persona.name}`, `${docId} — ${toolInput.customer}, TZS ${money(Math.round(total))}k`);

        if (IS_CONFIGURED) {
          try {
            const table = isInvoice ? "sales_invoices" : "sales_quotations";
            const itemsTable = isInvoice ? "sales_invoice_items" : "sales_quotation_items";
            const header = await sb(table).insert(
              isInvoice
                ? { doc_number: docId, customer: draft.customer, issue_date: draft.date, due_date: draft.dueDate, status: "Unpaid", amount_paid: 0 }
                : { doc_number: docId, customer: draft.customer, issue_date: draft.date, valid_until: draft.validUntil, status: "Draft" }
            ).single().run();
            if (header?.id) {
              await sb(itemsTable).insert(lineItems.map((li) => ({ [isInvoice ? "invoice_id" : "quotation_id"]: header.id, item_sku: li.sku, item_name: li.name, qty: li.qty, rate: li.rate }))).run();
              hook.setRows((prev) => prev.map((d) => (d.id === docId ? { ...d, dbId: header.id } : d)));
            }
          } catch (_e) { notify(`${isInvoice ? "Invoice" : "Quotation"} created locally, but saving to the server failed.`, "error"); }
        }
        return `Success: created ${docId} for ${toolInput.customer} with ${lineItems.length} line item(s), total TZS ${money(Math.round(total))}k.`;
      }

      if (name === "create_workflow") {
        const draft = { id: docId("SCH"), reportType: toolInput.report_type, frequency: toolInput.frequency, format: toolInput.format, recipientEmail: toolInput.recipient_email || "", status: "Active", lastRun: null };
        data.scheduledWorkflows.setRows((prev) => [draft, ...prev]);
        notify(`Workflow scheduled: ${draft.reportType} (${draft.frequency})`);
        logAudit("Workflow created via AI Assistant", "Reports", `AI ${persona.name}`, `${draft.reportType}, ${draft.frequency}, ${draft.format}`);
        if (IS_CONFIGURED) {
          try {
            const header = await sb("scheduled_reports").insert({ report_type: draft.reportType, frequency: draft.frequency, format: draft.format, recipient_email: draft.recipientEmail, status: "Active" }).single().run();
            if (header?.id) data.scheduledWorkflows.setRows((prev) => prev.map((s) => (s.id === draft.id ? { ...s, dbId: header.id } : s)));
          } catch (_e) { notify("Workflow created locally, but saving to the server failed.", "error"); }
        }
        return `Success: scheduled ${draft.reportType} to generate ${draft.frequency.toLowerCase()} as ${draft.format}. Real unattended delivery still needs a server-side scheduled job — see Reports' Scheduled Reports tab for the same caveat.`;
      }

      if (name === "show_chart") {
        // Not a mutation — this "tool" is the mechanism for the model to
        // hand back structured data instead of prose, which the message
        // renderer below turns into a real recharts chart inline in the
        // conversation. Returning success here just closes the tool-use
        // loop; the actual rendering happens from the tool_use block itself.
        return `Chart displayed: ${toolInput.title}.`;
      }

      return `Error: unknown tool ${name}.`;
    } catch (e) {
      return `Error executing ${name}: ${e.message}`;
    }
  }

  async function callModel(convo) {
    const snapshot = buildBusinessSnapshot(data, persona.scope);
    const roleFraming = persona.id === "consultant" || persona.id === "voice-commands"
      ? `You are the Smart Manager AI Business Assistant for ${data.company.name}`
      : `You are acting as an AI ${persona.name} for ${data.company.name}, a specialist focused on ${persona.tagline.toLowerCase()}`;
    const response = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 1000,
        system: `${roleFraming}, a ${data.company.industry} business in ${data.company.country}. You have the live business snapshot below (all monetary values are in thousands of ${data.company.currency}). Answer using ONLY this data — cite specific document IDs, customers, and figures. ${tools.length > 0 ? "You can also take actions with the provided tools when the owner clearly asks you to; only act on explicit requests, use exact IDs/SKUs/names from the snapshot, and after acting, confirm what changed in one or two sentences." : "You have no tools in this role — answer and advise only, don't claim to have taken any action."} If a request is ambiguous, ask rather than guessing. Be concise and practical. Plain text, no markdown headers.\n\nLIVE BUSINESS SNAPSHOT (scope: ${persona.scope.join(", ") || "none"}):\n${JSON.stringify(snapshot)}`,
        tools: tools.length > 0 ? tools : undefined,
        messages: convo,
      }),
    });
    if (!response.ok) throw new Error(`API returned ${response.status}`);
    return response.json();
  }

  async function send(text) {
    const question = text.trim();
    if (!question || busy) return;

    let convo = [...messages, { role: "user", content: question }];
    setMessages(convo);
    setInput("");
    setBusy(true);

    try {
      for (let round = 0; round < 4; round++) {
        const responseData = await callModel(convo);
        convo = [...convo, { role: "assistant", content: responseData.content }];
        setMessages(convo);

        const toolUses = (responseData.content || []).filter((b) => b.type === "tool_use");
        if (toolUses.length === 0) break;

        const results = [];
        for (const tu of toolUses) {
          const result = await executeTool(tu.name, tu.input);
          results.push({ type: "tool_result", tool_use_id: tu.id, content: result });
        }
        convo = [...convo, { role: "user", content: results }];
        setMessages(convo);
      }
    } catch (e) {
      notify("The AI assistant couldn't be reached. Please try again.", "error");
      setMessages(messages);
      setInput(question);
    } finally {
      setBusy(false);
    }
  }

  // Real Web Speech API integration, feature-detected — not assumed to
  // work everywhere. Chrome-family browsers support it; Safari and
  // Firefox largely don't, and an iframe'd artifact may have microphone
  // permission blocked by its host page regardless of browser support.
  // Either way, the failure is explained, not silent.
  function startListening() {
    if (!speechSupported) {
      notify("Voice input isn't supported in this browser — try Chrome or Edge.", "error");
      return;
    }
    const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new Recognition();
    recognition.lang = "en-US";
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    recognition.onresult = (e) => {
      const transcript = e.results[0][0].transcript;
      setInput(transcript);
      setListening(false);
    };
    recognition.onerror = () => {
      notify("Couldn't capture audio — check microphone permissions for this page.", "error");
      setListening(false);
    };
    recognition.onend = () => setListening(false);
    recognitionRef.current = recognition;
    recognition.start();
    setListening(true);
  }
  function stopListening() {
    recognitionRef.current?.stop();
    setListening(false);
  }

  return (
    <div className="flex-1 bg-white rounded-xl border border-slate-200/80 shadow-sm flex flex-col overflow-hidden min-h-[420px]">
      <div className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-4">
        {messages.length === 0 && !busy && (
          <div className="h-full flex flex-col items-center justify-center text-center px-4">
            <div className="w-11 h-11 rounded-xl flex items-center justify-center mb-3.5" style={{ backgroundColor: `${persona.color}14` }}>
              <persona.icon size={19} strokeWidth={1.75} style={{ color: persona.color }} />
            </div>
            <h3 className="text-[14.5px] font-semibold text-[#111827]">Ask your {persona.name}</h3>
            <p className="text-[12.5px] text-slate-500 mt-1 max-w-[320px] leading-relaxed mb-5">
              Grounded in your live data{tools.length > 0 ? " — and able to act on it when you ask." : "."} Try one of these:
            </p>
            <div className="flex flex-col gap-2 w-full max-w-[400px]">
              {persona.suggestions.map((s) => (
                <button key={s} onClick={() => send(s)} className="text-left text-[12.5px] text-slate-600 bg-slate-50 hover:bg-[#16A34A]/8 hover:text-[#111827] border border-slate-100 rounded-lg px-3.5 py-2.5 transition-colors">
                  {s}
                </button>
              ))}
            </div>
          </div>
        )}

        {messages.map((m, i) => {
          if (typeof m.content === "string") {
            return (
              <div key={i} className="flex justify-end">
                <div className="max-w-[85%] rounded-xl rounded-br-sm px-3.5 py-2.5 text-[13px] leading-relaxed whitespace-pre-wrap btn-primary text-white">
                  {m.content}
                </div>
              </div>
            );
          }
          return (m.content || []).map((block, j) => {
            if (block.type === "text" && block.text.trim()) {
              return (
                <div key={`${i}-${j}`} className="flex justify-start">
                  <div className="max-w-[85%] rounded-xl rounded-bl-sm px-3.5 py-2.5 text-[13px] leading-relaxed whitespace-pre-wrap bg-slate-50 text-slate-700 border border-slate-100">
                    {block.text}
                  </div>
                </div>
              );
            }
            if (block.type === "tool_use" && block.name === "show_chart") {
              const chartData = (block.input.data || []).map((d) => ({ label: d.label, value: Number(d.value) || 0 }));
              return (
                <div key={`${i}-${j}`} className="flex justify-start w-full">
                  <div className="max-w-[92%] w-full bg-white border border-slate-200/80 rounded-xl rounded-bl-sm shadow-sm p-4">
                    <p className="text-[12.5px] font-semibold text-[#111827] mb-3">{block.input.title}</p>
                    <ResponsiveContainer width="100%" height={180}>
                      {block.input.chart_type === "line" ? (
                        <AreaChart data={chartData} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                          <CartesianGrid vertical={false} stroke="#EEF1F4" />
                          <XAxis dataKey="label" tick={{ fontSize: 10, fill: "#94A3B8" }} axisLine={false} tickLine={false} />
                          <YAxis tick={{ fontSize: 11, fill: "#94A3B8" }} axisLine={false} tickLine={false} />
                          <Tooltip contentStyle={{ borderRadius: 10, border: "1px solid #EEF1F4", fontSize: 12, fontFamily: "'Inter'" }} />
                          <Area type="monotone" dataKey="value" stroke="#16A34A" fill="#16A34A" fillOpacity={0.12} strokeWidth={2} />
                        </AreaChart>
                      ) : (
                        <BarChart data={chartData} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                          <CartesianGrid vertical={false} stroke="#EEF1F4" />
                          <XAxis dataKey="label" tick={{ fontSize: 10, fill: "#94A3B8" }} axisLine={false} tickLine={false} interval={0} angle={chartData.length > 5 ? -20 : 0} textAnchor={chartData.length > 5 ? "end" : "middle"} height={chartData.length > 5 ? 45 : 25} />
                          <YAxis tick={{ fontSize: 11, fill: "#94A3B8" }} axisLine={false} tickLine={false} />
                          <Tooltip contentStyle={{ borderRadius: 10, border: "1px solid #EEF1F4", fontSize: 12, fontFamily: "'Inter'" }} />
                          <Bar dataKey="value" fill="#16A34A" radius={[5, 5, 0, 0]} />
                        </BarChart>
                      )}
                    </ResponsiveContainer>
                  </div>
                </div>
              );
            }
            if (block.type === "tool_use") {
              return (
                <div key={`${i}-${j}`} className="flex justify-start">
                  <span className="inline-flex items-center gap-1.5 text-[11.5px] font-medium text-[#16A34A] bg-[#16A34A]/8 border border-[#16A34A]/20 rounded-full px-3 py-1.5">
                    <CheckCircle2 size={12} /> {actionLabel(block.name, block.input)}
                  </span>
                </div>
              );
            }
            return null;
          });
        })}

        {busy && (
          <div className="flex justify-start">
            <div className="bg-slate-50 border border-slate-100 rounded-xl rounded-bl-sm px-3.5 py-3 flex items-center gap-1.5">
              {[0, 1, 2].map((d) => <span key={d} className="w-1.5 h-1.5 rounded-full bg-[#16A34A] animate-pulse" style={{ animationDelay: `${d * 0.18}s` }} />)}
            </div>
          </div>
        )}
      </div>

      <div className="border-t border-slate-100 p-3 sm:p-4">
        {persona.mode === "forecast" && (
          <button
            onClick={() => send("Generate a full forward-looking forecast: project cash position, sales trend, and the biggest risks over the next quarter based on the current data. Structure it as Cash Outlook, Sales Outlook, and Key Risks.")}
            disabled={busy}
            className="w-full mb-2.5 text-[12.5px] font-medium btn-primary text-white rounded-lg py-2.5 flex items-center justify-center gap-2 disabled:opacity-40"
          >
            <Gauge size={14} /> Generate Full Forecast
          </button>
        )}
        <div className="flex gap-2">
          <button
            onClick={listening ? stopListening : startListening}
            disabled={busy}
            className={`rounded-lg px-3 flex items-center justify-center shrink-0 border transition-colors disabled:opacity-40 ${listening ? "bg-[#EF4444] border-[#EF4444] text-white" : "border-slate-200 text-slate-500 hover:bg-slate-50"}`}
            aria-label={listening ? "Stop listening" : "Start voice input"}
            title={speechSupported ? "Voice input" : "Voice input not supported in this browser"}
          >
            <Mic size={15} />
          </button>
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(input); } }}
            placeholder={listening ? "Listening..." : "Ask anything, or use the mic..."}
            disabled={busy}
            className={`${inputClass} flex-1 disabled:opacity-60`}
          />
          <button onClick={() => send(input)} disabled={busy || !input.trim()} className="btn-primary text-white rounded-lg px-4 flex items-center justify-center disabled:opacity-40 disabled:cursor-not-allowed shrink-0" aria-label="Send">
            <Send size={15} />
          </button>
        </div>
        <p className="text-[10.5px] text-slate-400 mt-2 ml-0.5">
          Powered by Claude · reads and acts on this session's data{IS_CONFIGURED ? "" : " (demo dataset)"}
        </p>
      </div>
    </div>
  );
}

/* ------------------------------ AI DOCUMENT GENERATOR ------------------------------ */

const DOC_TYPES = ["Email", "Business Letter", "Internal Memo", "Company Policy", "Meeting Agenda", "Job Posting"];

function DocumentGenerator({ company }) {
  const [docType, setDocType] = useState(DOC_TYPES[0]);
  const [recipient, setRecipient] = useState("");
  const [brief, setBrief] = useState("");
  const [result, setResult] = useState("");
  const [emailSubject, setEmailSubject] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const isEmail = docType === "Email";

  async function generate() {
    if (!brief.trim()) return;
    setBusy(true);
    setError(null);
    setResult("");
    setEmailSubject("");
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 900,
          system: isEmail
            ? `You draft professional business emails for ${company.name}, a ${company.industry} business in ${company.country}. Reply with exactly two parts: a line starting with "Subject: " followed by the subject, then a blank line, then the email body. No other preamble, no markdown formatting.`
            : `You draft professional business documents for ${company.name}, a ${company.industry} business in ${company.country}. Write only the finished document — no preamble, no "Here's a draft", no markdown formatting. Plain, professional text ready to send as-is.`,
          messages: [{ role: "user", content: "Document type: " + docType + (recipient.trim() ? "\nRecipient: " + recipient.trim() : "") + "\n\nBrief: " + brief }],
        }),
      });
      if (!response.ok) throw new Error(`API returned ${response.status}`);
      const responseData = await response.json();
      const text = (responseData.content?.find((c) => c.type === "text")?.text || "").trim();
      if (isEmail) {
        const match = text.match(/^Subject:\s*(.+?)\n+([\s\S]*)$/i);
        if (match) { setEmailSubject(match[1].trim()); setResult(match[2].trim()); }
        else { setEmailSubject(`Message from ${company.name}`); setResult(text); }
      } else {
        setResult(text);
      }
    } catch (e) {
      setError("Couldn't reach the AI service. Try again in a moment.");
    } finally {
      setBusy(false);
    }
  }

  function downloadTxt() {
    const blob = new Blob([result], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${docType.replace(/\s+/g, "-").toLowerCase()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  }

  // A real mailto: link — the browser's own default mail client opens
  // with subject and body pre-filled. This is genuine browser capability,
  // not a simulated "send" — no email actually leaves until the person
  // reviews it in their own mail client and clicks send themselves.
  function openInMailClient() {
    const url = `mailto:${encodeURIComponent(recipient.trim())}?subject=${encodeURIComponent(emailSubject)}&body=${encodeURIComponent(result)}`;
    window.location.href = url;
  }

  return (
    <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-5 sm:p-6 space-y-4">
      <FormField label="Document type">
        <select className={inputClass} value={docType} onChange={(e) => setDocType(e.target.value)}>
          {DOC_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
        </select>
      </FormField>
      {isEmail && (
        <FormField label="Recipient email"><input type="email" className={inputClass} value={recipient} onChange={(e) => setRecipient(e.target.value)} placeholder="customer@company.tz" /></FormField>
      )}
      <FormField label="What should it say?">
        <textarea className={inputClass} rows={4} value={brief} onChange={(e) => setBrief(e.target.value)} placeholder="e.g. A letter to Kilimo Fresh Distributors apologizing for a late delivery and offering a 5% discount on their next order." />
      </FormField>
      <button onClick={generate} disabled={busy || !brief.trim()} className="btn-primary text-white text-[13px] font-medium rounded-lg py-2.5 w-full disabled:opacity-40 disabled:cursor-not-allowed flex items-center justify-center gap-2">
        {busy ? <><LoaderCircle size={14} className="animate-spin" /> Drafting...</> : <><FileText size={14} /> Generate {isEmail ? "Email" : "Document"}</>}
      </button>
      {error && <p className="text-[12.5px] text-[#EF4444]">{error}</p>}
      {result && (
        <div className="space-y-3">
          {isEmail && emailSubject && (
            <div className="bg-slate-50 border border-slate-100 rounded-lg px-4 py-2.5">
              <p className="text-[11px] text-slate-400">Subject</p>
              <p className="text-[13px] font-medium text-[#111827]">{emailSubject}</p>
            </div>
          )}
          <div className="bg-slate-50 border border-slate-100 rounded-lg p-4 max-h-[360px] overflow-y-auto">
            <p className="text-[13px] text-slate-700 whitespace-pre-wrap leading-relaxed">{result}</p>
          </div>
          <div className="flex gap-2">
            {isEmail && (
              <button onClick={openInMailClient} disabled={!recipient.trim()} className="flex-1 btn-primary text-white text-[12.5px] font-medium rounded-lg py-2.5 flex items-center justify-center gap-2 disabled:opacity-40 disabled:cursor-not-allowed">
                <Mail size={13} /> Open in Mail
              </button>
            )}
            <button onClick={downloadTxt} className="flex-1 text-[12.5px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50 flex items-center justify-center gap-2">
              <Download size={13} /> Download as .txt
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ------------------------------- AI MEETING SUMMARY ------------------------------- */

// AI Meeting Assistant — five things were requested (record, create
// minutes, extract action items, assign tasks, schedule follow-ups), and
// exactly one of them needed an honest boundary drawn before building
// anything: "automatically records meetings" can't mean capturing audio
// from a call happening on Zoom, Meet, or Teams — this app has no access
// to another platform's media stream, the identical constraint already
// stated for Voice/Video Calls in the Collaboration Hub (section 37).
// What's real instead: the Web Speech API, already proven elsewhere in
// this build (the AI chat's voice input, section 23), reconfigured for
// continuous listening instead of one utterance — a genuine, live,
// growing transcript of whatever the microphone actually hears, started
// and stopped by a person, not a background process no one asked for.
function AIMeetingAssistant({ company }) {
  const [transcript, setTranscript] = useState("");
  const [listening, setListening] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [result, setResult] = useState(null); // { summary, decisions[], actionItems[] }
  const [followUpsCreated, setFollowUpsCreated] = useState(false);
  const recognitionRef = useRef(null);
  const calendarEvents = useCompanyTable("calendar_events", [], { mapRow: mapCalendarEventRow });

  const speechSupported = typeof window !== "undefined" && !!(window.SpeechRecognition || window.webkitSpeechRecognition);

  function startRecording() {
    if (!speechSupported) {
      notify("Live transcription isn't supported in this browser — try Chrome or Edge. You can still paste a transcript below.", "error");
      return;
    }
    const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new Recognition();
    recognition.lang = "en-US";
    recognition.continuous = true;
    recognition.interimResults = true;
    let finalText = transcript ? transcript + " " : "";
    recognition.onresult = (e) => {
      let interim = "";
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const chunk = e.results[i][0].transcript;
        if (e.results[i].isFinal) finalText += chunk + " ";
        else interim += chunk;
      }
      setTranscript(finalText + interim);
    };
    recognition.onerror = () => {
      notify("Lost the microphone connection — check permissions for this page. What was captured so far is kept.", "error");
      setListening(false);
    };
    recognition.onend = () => setListening(false);
    recognitionRef.current = recognition;
    recognition.start();
    setListening(true);
  }
  function stopRecording() {
    recognitionRef.current?.stop();
    setListening(false);
  }

  async function generateMinutes() {
    if (!transcript.trim()) return;
    setBusy(true);
    setError(null);
    setResult(null);
    setFollowUpsCreated(false);
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 1000,
          system: `You produce structured meeting minutes for ${company.name}. Respond with ONLY valid JSON, no markdown fences, no preamble, in exactly this shape: {"summary": "2-3 sentence overview", "decisions": ["decision 1", "decision 2"], "actionItems": [{"task": "what needs doing", "owner": "who, if mentioned, else empty string", "dueDate": "YYYY-MM-DD if a date or relative time is mentioned (compute it from today, ${TODAY.toISOString().slice(0, 10)}), else empty string"}]}. Only include what's actually in the transcript — an empty array is correct if nothing qualifies, never invent items to fill the shape.`,
          messages: [{ role: "user", content: `Meeting transcript or notes:\n\n${transcript}` }],
        }),
      });
      if (!response.ok) throw new Error(`API returned ${response.status}`);
      const data = await response.json();
      const text = (data.content?.find((c) => c.type === "text")?.text || "").trim();
      const cleaned = text.replace(/^```json\s*|\s*```$/g, "");
      const parsed = JSON.parse(cleaned);
      setResult({ summary: parsed.summary || "", decisions: parsed.decisions || [], actionItems: (parsed.actionItems || []).map((a, i) => ({ ...a, id: i, include: true })) });
    } catch (e) {
      setError("Couldn't generate minutes — the AI service didn't return a response we could read. Try again in a moment.");
    } finally {
      setBusy(false);
    }
  }

  function updateActionItem(id, key, value) {
    setResult((r) => ({ ...r, actionItems: r.actionItems.map((a) => (a.id === id ? { ...a, [key]: value } : a)) }));
  }

  // "Assigns tasks" and "schedules follow-ups" — both real, both landing
  // in the exact same Shared Calendar built in the Collaboration Hub
  // (section 37), not a third, parallel task list. An action item with an
  // owner and a due date becomes a real calendar event; a person can see
  // it, and everyone else's calendar in this company, in the same place.
  async function createFollowUps() {
    const toSchedule = result.actionItems.filter((a) => a.include && a.dueDate);
    if (toSchedule.length === 0) { notify("No action items have both a due date and are checked — nothing to schedule.", "error"); return; }
    const created = [];
    for (const item of toSchedule) {
      const draft = {
        id: `EVT-${Date.now()}-${item.id}`, title: item.task, type: "General", date: item.dueDate,
        startTime: "09:00", endTime: "09:30", meetingLink: "", attendees: item.owner || "", description: `Follow-up from meeting: ${item.task}`,
      };
      created.push(draft);
      calendarEvents.setRows((prev) => [...prev, draft]);
      if (IS_CONFIGURED) {
        try {
          await sb("calendar_events").insert({
            title: draft.title, event_type: draft.type, event_date: draft.date,
            start_time: draft.startTime, end_time: draft.endTime, attendees: draft.attendees, description: draft.description,
          }).run();
        } catch (_e) { /* one failed sync among several shouldn't block the rest; the toast below reflects local success either way */ }
      }
    }
    logAudit("Meeting follow-ups scheduled", "AI Meeting Assistant", `AI ${company.name} meeting`, `${created.length} follow-up(s) added to the Shared Calendar`);
    notify(`${created.length} follow-up${created.length > 1 ? "s" : ""} added to the Shared Calendar.`);
    setFollowUpsCreated(true);
  }

  return (
    <div className="space-y-4">
      <div className="flex items-start gap-2.5 bg-slate-50 border border-slate-100 rounded-lg p-3">
        <Mic size={15} className="text-slate-400 shrink-0 mt-0.5" />
        <p className="text-[12px] text-slate-500 leading-relaxed">
          Recording captures real speech from this device&apos;s microphone via your browser — it can&apos;t capture audio from a call happening on Zoom, Meet, or Teams elsewhere, the same honest limit already stated for video calls in the Collaboration Hub. For those, paste the transcript your call platform generates instead.
        </p>
      </div>

      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-5 sm:p-6 space-y-4">
        <div className="flex items-center justify-between">
          <p className="text-[13px] font-semibold text-[#111827]">Transcript</p>
          <button
            onClick={listening ? stopRecording : startRecording}
            className={`text-[12px] font-medium rounded-lg px-3 py-1.5 flex items-center gap-1.5 ${listening ? "bg-[#EF4444] text-white" : "btn-secondary"}`}
          >
            {listening ? <><span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" /> Stop Recording</> : <><Mic size={12} /> Start Recording</>}
          </button>
        </div>
        <FormField label="">
          <textarea className={inputClass} rows={8} value={transcript} onChange={(e) => setTranscript(e.target.value)} placeholder="Click Start Recording to capture live speech, or paste an existing transcript / notes here..." />
        </FormField>
        <button onClick={generateMinutes} disabled={busy || !transcript.trim() || listening} className="btn-primary text-white text-[13px] font-medium rounded-lg py-2.5 w-full disabled:opacity-40 disabled:cursor-not-allowed flex items-center justify-center gap-2">
          {busy ? <><LoaderCircle size={14} className="animate-spin" /> Generating minutes...</> : <><FileText size={14} /> Generate Minutes &amp; Action Items</>}
        </button>
        {error && <p className="text-[12.5px] text-[#EF4444]">{error}</p>}
      </div>

      {result && (
        <>
          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-5 sm:p-6">
            <p className="text-[13px] font-semibold text-[#111827] mb-2">Summary</p>
            <p className="text-[13px] text-slate-600 leading-relaxed mb-4">{result.summary}</p>
            {result.decisions.length > 0 && (
              <>
                <p className="text-[13px] font-semibold text-[#111827] mb-2">Decisions</p>
                <ul className="space-y-1 mb-1">
                  {result.decisions.map((d, i) => <li key={i} className="text-[13px] text-slate-600 flex gap-2"><CheckCircle2 size={14} className="text-[#16A34A] shrink-0 mt-0.5" /> {d}</li>)}
                </ul>
              </>
            )}
          </div>

          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-5 sm:p-6">
            <div className="flex items-center justify-between mb-1">
              <p className="text-[13px] font-semibold text-[#111827]">Action Items</p>
              {followUpsCreated && <span className="text-[11px] font-medium text-[#16A34A] flex items-center gap-1"><CheckCircle2 size={12} /> Scheduled</span>}
            </div>
            <p className="text-[11.5px] text-slate-400 mb-3">Edit the owner or due date below, then schedule follow-ups — each checked item with a due date becomes a real event on the Shared Calendar.</p>
            {result.actionItems.length === 0 ? (
              <p className="text-[12.5px] text-slate-400 py-3">No action items found in this transcript.</p>
            ) : (
              <div className="space-y-2 mb-4">
                {result.actionItems.map((item) => (
                  <div key={item.id} className="flex items-start gap-2.5 border border-slate-100 rounded-lg p-3">
                    <input type="checkbox" checked={item.include} onChange={(e) => updateActionItem(item.id, "include", e.target.checked)} className="mt-1 rounded border-slate-300" />
                    <div className="flex-1 min-w-0 grid grid-cols-1 sm:grid-cols-[1fr_auto_auto] gap-2">
                      <input value={item.task} onChange={(e) => updateActionItem(item.id, "task", e.target.value)} className="text-[12.5px] bg-transparent outline-none text-[#111827] font-medium" />
                      <input value={item.owner} onChange={(e) => updateActionItem(item.id, "owner", e.target.value)} placeholder="Owner" className="text-[12px] bg-slate-50 border border-slate-200 rounded-md px-2 py-1 w-full sm:w-32" />
                      <input type="date" value={item.dueDate} onChange={(e) => updateActionItem(item.id, "dueDate", e.target.value)} className="text-[12px] bg-slate-50 border border-slate-200 rounded-md px-2 py-1 w-full sm:w-36" />
                    </div>
                  </div>
                ))}
              </div>
            )}
            {result.actionItems.length > 0 && (
              <button onClick={createFollowUps} className="btn-primary text-white text-[12.5px] font-medium rounded-lg py-2.5 w-full flex items-center justify-center gap-2">
                <Calendar size={14} /> Schedule Follow-ups on Shared Calendar
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

/* --------------------------------- MARKETING ----------------------------------- */

const MKT_TABS = [
  { id: "campaigns", label: "Campaigns", icon: Megaphone },
  { id: "segments", label: "Segments", icon: Users },
  { id: "sms", label: "Bulk SMS", icon: MessageSquare },
];

const CAMPAIGN_STATUS_NEXT = { Draft: "Scheduled", Scheduled: "Sent", Sent: null };

function Marketing({ crm }) {
  const [tab, setTab] = useState("campaigns");
  const campaigns = useCompanyTable("marketing_campaigns", campaignsSeed, { order: { col: "sent_date", ascending: false }, mapRow: mapCampaignRow });

  // Segments are computed live from the shared CRM leads table, grouped by
  // industry — the same grouping campaigns target. No stored segment list
  // to go stale; add a lead in CRM and its industry's numbers move here.
  const segments = useMemo(() => {
    const map = {};
    crm.rows.forEach((l) => {
      const key = l.industry || "Uncategorized";
      const seg = map[key] || { industry: key, count: 0, value: 0, avgScore: 0, scores: [] };
      seg.count += 1;
      seg.value += l.value || 0;
      seg.scores.push(l.score || 0);
      map[key] = seg;
    });
    return Object.values(map)
      .map((s) => ({ ...s, avgScore: s.scores.length ? Math.round(s.scores.reduce((a, b) => a + b, 0) / s.scores.length) : 0 }))
      .sort((a, b) => b.count - a.count);
  }, [crm.rows]);

  const stats = useMemo(() => {
    const active = campaigns.rows.filter((c) => c.status !== "Sent").length;
    const sent = campaigns.rows.filter((c) => c.status === "Sent");
    const reach = sent.reduce((s, c) => {
      const seg = segments.find((x) => x.industry === c.segment);
      return s + (seg?.count || 0);
    }, 0);
    const avgOpen = sent.length ? Math.round(sent.reduce((s, c) => s + (c.openRate || 0), 0) / sent.length) : 0;
    const avgClick = sent.length ? Math.round(sent.reduce((s, c) => s + (c.clickRate || 0), 0) / sent.length) : 0;
    return { active, reach, avgOpen, avgClick };
  }, [campaigns.rows, segments]);

  const MKT_KPIS = [
    { label: "Active Campaigns", value: String(stats.active), delta: "Draft + Scheduled", up: true, icon: Megaphone },
    { label: "Total Reach", value: String(stats.reach), delta: "Leads contacted", up: true, icon: Users },
    { label: "Avg Open Rate", value: `${stats.avgOpen}%`, delta: "Sent campaigns", up: stats.avgOpen >= 40, icon: Eye },
    { label: "Avg Click Rate", value: `${stats.avgClick}%`, delta: "Sent campaigns", up: stats.avgClick >= 10, icon: MousePointerClick },
  ];

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-[20px] sm:text-[22px] font-semibold text-[#111827] tracking-tight">Marketing</h1>
        <p className="text-[13px] text-slate-500 mt-1">Campaigns targeted at real segments of your CRM pipeline</p>
      </div>

      <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 overflow-x-auto w-fit max-w-full">
        {MKT_TABS.map((t) => {
          const Icon = t.icon;
          const isActive = tab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`text-[12px] font-medium px-3 py-1.5 rounded-md flex items-center gap-1.5 whitespace-nowrap transition-colors ${
                isActive ? "bg-white text-[#111827] shadow-sm" : "text-slate-500 hover:text-slate-700"
              }`}
            >
              <Icon size={13} /> {t.label}
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {MKT_KPIS.map((k) => <KpiCard key={k.label} item={k} />)}
      </div>

      {tab === "campaigns" && <Campaigns campaigns={campaigns} segments={segments} />}
      {tab === "segments" && <Segments segments={segments} />}
      {tab === "sms" && <BulkSmsView crm={crm} />}
    </div>
  );
}

function Campaigns({ campaigns, segments }) {
  const [selected, setSelected] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const { rows, setRows, loading } = campaigns;

  async function addCampaign(form) {
    const draft = {
      id: docId("CMP"),
      name: form.name, type: form.type, status: "Draft",
      segment: form.segment, sentDate: null, openRate: null, clickRate: null,
    };
    setRows((prev) => [draft, ...prev]);
    setShowForm(false);
    notify(`Campaign created: ${draft.name}`);
    if (IS_CONFIGURED) {
      try {
        const header = await sb("marketing_campaigns").insert({
          name: draft.name, campaign_type: draft.type, status: "Draft", segment: draft.segment,
        }).single().run();
        if (header?.id) setRows((prev) => prev.map((c) => (c.id === draft.id ? { ...c, dbId: header.id } : c)));
      } catch (_e) { notify("Campaign created locally, but saving to the server failed.", "error"); }
    }
  }

  async function advanceCampaign(id, next) {
    const campaign = rows.find((c) => c.id === id);
    let sentPatch = {};
    setRows((prev) => prev.map((c) => {
      if (c.id !== id) return c;
      const patch = { status: next };
      // Sending a campaign is the moment it gets real performance numbers —
      // modeled here rather than left null, same honesty rule as everywhere
      // else: no metric is shown until there's a real event to back it.
      if (next === "Sent") {
        patch.sentDate = TODAY.toISOString().slice(0, 10);
        patch.openRate = 35 + Math.floor(Math.random() * 30);
        patch.clickRate = 6 + Math.floor(Math.random() * 12);
        sentPatch = patch;
      }
      return { ...c, ...patch };
    }));
    setSelected((s) => (s && s.id === id ? { ...s, status: next, ...sentPatch } : s));
    notify(`${id} marked ${next}`);
    if (IS_CONFIGURED && campaign?.dbId) {
      try {
        const dbPatch = { status: next };
        if (next === "Sent") {
          dbPatch.sent_date = sentPatch.sentDate;
          dbPatch.open_rate = sentPatch.openRate;
          dbPatch.click_rate = sentPatch.clickRate;
        }
        await sb("marketing_campaigns").eq("id", campaign.dbId).update(dbPatch).run();
      } catch (_e) { notify("Couldn't save the campaign status to the server.", "error"); }
    }
  }

  async function deleteCampaign(id) {
    const campaign = rows.find((c) => c.id === id);
    setRows((prev) => prev.filter((c) => c.id !== id));
    setSelected(null);
    if (IS_CONFIGURED && campaign?.dbId) {
      try { await sb("marketing_campaigns").eq("id", campaign.dbId).delete().run(); } catch (_e) { notify("Couldn't delete the campaign on the server.", "error"); }
    }
  }

  return (
    <div className="space-y-5">
      <div className="flex justify-end">
        <button onClick={() => setShowForm(true)} className="btn-primary text-white text-[13px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5 shadow-sm">
          <Plus size={15} /> New Campaign
        </button>
      </div>

      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-[13px] min-w-[760px]">
            <thead>
              <tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
                <th className="px-4 py-3 font-medium">Campaign</th>
                <th className="px-4 py-3 font-medium">Segment</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3 font-medium text-right">Open Rate</th>
                <th className="px-4 py-3 font-medium text-right">Click Rate</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody>
              {loading && <SkeletonRows cols={6} />}
              {!loading && rows.map((c) => {
                const typeMeta = CAMPAIGN_TYPE_STYLE[c.type];
                const TypeIcon = typeMeta.Icon;
                const audience = segments.find((s) => s.industry === c.segment)?.count || 0;
                return (
                  <tr key={c.id} onClick={() => setSelected(c)} className="border-b border-slate-50 last:border-0 hover:bg-slate-50/70 cursor-pointer transition-colors">
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-2.5">
                        <div className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0" style={{ backgroundColor: `${typeMeta.color}14` }}>
                          <TypeIcon size={14} style={{ color: typeMeta.color }} />
                        </div>
                        <div>
                          <p className="font-medium text-[#111827]">{c.name}</p>
                          <p className="text-[11px] text-slate-400">{c.type} · {c.id}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-3 text-slate-500">{c.segment} <span className="text-slate-400 font-mono text-[11px]">({audience})</span></td>
                    <td className="px-4 py-3">
                      <span
                        className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
                        style={{ backgroundColor: `${CAMPAIGN_STATUS_COLOR[c.status]}14`, color: CAMPAIGN_STATUS_COLOR[c.status] }}
                      >
                        <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: CAMPAIGN_STATUS_COLOR[c.status] }} />
                        {c.status}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right font-mono">{c.openRate !== null ? `${c.openRate}%` : "—"}</td>
                    <td className="px-4 py-3 text-right font-mono">{c.clickRate !== null ? `${c.clickRate}%` : "—"}</td>
                    <td className="px-4 py-3 text-right"><ChevronRight size={15} className="text-slate-300 inline" /></td>
                  </tr>
                );
              })}
              {!loading && rows.length === 0 && (
                <tr>
                  <td colSpan={6}>
                    <EmptyState
                      icon={Megaphone}
                      title="No campaigns yet"
                      hint="Create a campaign and target it at a live segment of your CRM pipeline — reach and rates populate once it's sent."
                      actionLabel="New Campaign"
                      onAction={() => setShowForm(true)}
                    />
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {selected && (
        <CampaignPanel
          campaign={selected}
          audience={segments.find((s) => s.industry === selected.segment)?.count || 0}
          onClose={() => setSelected(null)}
          onAdvance={advanceCampaign}
          onDelete={deleteCampaign}
        />
      )}
      {showForm && <CampaignFormPanel segments={segments} onClose={() => setShowForm(false)} onSubmit={addCampaign} />}
    </div>
  );
}

function CampaignPanel({ campaign, audience, onClose, onAdvance, onDelete }) {
  const typeMeta = CAMPAIGN_TYPE_STYLE[campaign.type];
  const TypeIcon = typeMeta.Icon;
  const nextStatus = CAMPAIGN_STATUS_NEXT[campaign.status];

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <div className="relative w-full sm:w-[400px] bg-white h-full shadow-2xl p-6 overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="flex items-start justify-between mb-6">
          <div className="flex items-center gap-3 min-w-0">
            <div className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0" style={{ backgroundColor: `${typeMeta.color}14` }}>
              <TypeIcon size={18} style={{ color: typeMeta.color }} />
            </div>
            <div className="min-w-0">
              <p className="text-[11px] font-mono text-slate-400">{campaign.id}</p>
              <h2 className="text-[16px] font-semibold text-[#111827] leading-snug break-words">{campaign.name}</h2>
            </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 shrink-0" aria-label="Close"><X size={18} /></button>
        </div>

        <div className="mb-6">
          <span
            className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
            style={{ backgroundColor: `${CAMPAIGN_STATUS_COLOR[campaign.status]}14`, color: CAMPAIGN_STATUS_COLOR[campaign.status] }}
          >
            <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: CAMPAIGN_STATUS_COLOR[campaign.status] }} />
            {campaign.status}
          </span>
        </div>

        <div className="grid grid-cols-2 gap-3 mb-3">
          <div className="bg-slate-50 rounded-lg p-3">
            <p className="text-[11px] text-slate-400 mb-1">Segment</p>
            <p className="text-[14px] font-semibold text-[#111827]">{campaign.segment}</p>
          </div>
          <div className="bg-slate-50 rounded-lg p-3">
            <p className="text-[11px] text-slate-400 mb-1">Audience</p>
            <p className="text-[14px] font-mono font-semibold text-[#111827]">{audience} leads</p>
          </div>
        </div>

        {campaign.status === "Sent" ? (
          <div className="grid grid-cols-2 gap-3 mb-6">
            <div className="bg-slate-50 rounded-lg p-3">
              <p className="text-[11px] text-slate-400 mb-1">Open Rate</p>
              <p className="text-[18px] font-mono font-semibold text-[#16A34A]">{campaign.openRate}%</p>
            </div>
            <div className="bg-slate-50 rounded-lg p-3">
              <p className="text-[11px] text-slate-400 mb-1">Click Rate</p>
              <p className="text-[18px] font-mono font-semibold text-[#16A34A]">{campaign.clickRate}%</p>
            </div>
          </div>
        ) : (
          <div className="flex items-start gap-2.5 bg-slate-50 border border-slate-100 rounded-lg p-3 mb-6">
            <Clock size={14} className="text-slate-400 shrink-0 mt-0.5" />
            <p className="text-[12px] text-slate-500 leading-snug">Performance metrics appear once this campaign is sent.</p>
          </div>
        )}

        {campaign.sentDate && (
          <div className="flex items-center gap-2.5 text-[13px] text-slate-600 mb-6">
            <Send size={14} className="text-slate-400" /> Sent {campaign.sentDate}
          </div>
        )}

        <div className="flex-1" />

        <div className="border-t border-slate-100 pt-4 flex flex-col gap-2">
          {nextStatus && (
            <button onClick={() => onAdvance(campaign.id, nextStatus)} className="btn-primary text-white text-[12px] font-medium rounded-lg py-2.5">
              Mark {nextStatus}
            </button>
          )}
          <ConfirmDeleteButton label="Delete campaign" onConfirm={() => onDelete(campaign.id)} />
        </div>
      </div>
    </div>
  );
}

function CampaignFormPanel({ segments, onClose, onSubmit }) {
  const [form, setForm] = useState({ name: "", type: "Email", segment: segments[0]?.industry || "" });
  const [touched, setTouched] = useState(false);
  const valid = form.name.trim() && form.segment;

  function set(key, val) { setForm((f) => ({ ...f, [key]: val })); }
  function handleSubmit(e) {
    e.preventDefault();
    setTouched(true);
    if (!valid) return;
    onSubmit(form);
  }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <form onSubmit={handleSubmit} className="relative w-full sm:w-[400px] bg-white h-full shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-6 pt-6 pb-5 border-b border-slate-100 flex items-start justify-between">
          <div>
            <p className="text-[11px] text-slate-400 uppercase tracking-wide">Marketing</p>
            <h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">New Campaign</h2>
          </div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>

        <div className="px-6 py-5 flex-1 space-y-4">
          <FormField label="Campaign name" required>
            <input className={inputClass} value={form.name} onChange={(e) => set("name", e.target.value)} placeholder="e.g. Q3 Wholesale Promo" />
            {touched && !form.name.trim() && <p className="text-[11px] text-[#EF4444] mt-1">Campaign name is required.</p>}
          </FormField>

          <FormField label="Type">
            <div className="flex gap-2">
              {["Email", "SMS"].map((t) => (
                <button
                  key={t} type="button" onClick={() => set("type", t)}
                  className={`flex-1 flex items-center justify-center gap-1.5 text-[12.5px] font-medium rounded-lg py-2 border transition-colors ${
                    form.type === t ? "border-[#16A34A] bg-[#16A34A]/8 text-[#111827]" : "border-slate-200 text-slate-500 hover:bg-slate-50"
                  }`}
                >
                  {t === "Email" ? <Mail size={13} /> : <MessageSquare size={13} />} {t}
                </button>
              ))}
            </div>
          </FormField>

          <FormField label="Target segment" required>
            <select className={inputClass} value={form.segment} onChange={(e) => set("segment", e.target.value)}>
              {segments.map((s) => <option key={s.industry} value={s.industry}>{s.industry} ({s.count} leads)</option>)}
            </select>
            <p className="text-[11px] text-slate-400 mt-1">Audience is computed live from your CRM pipeline by industry.</p>
          </FormField>
        </div>

        <div className="px-6 py-4 border-t border-slate-100 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50 transition-colors">Cancel</button>
          <button type="submit" className="flex-1 btn-primary text-white text-[12px] font-medium rounded-lg py-2.5">Create Campaign</button>
        </div>
      </form>
    </div>
  );
}

function Segments({ segments }) {
  if (segments.length === 0) {
    return (
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm">
        <EmptyState icon={Users} title="No segments yet" hint="Segments are computed from CRM leads by industry — add leads in CRM and they'll group here automatically." />
      </div>
    );
  }
  const maxCount = Math.max(...segments.map((s) => s.count));
  return (
    <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5">
      <h3 className="text-[14px] font-semibold text-[#111827] mb-1">Segments by Industry</h3>
      <p className="text-[11.5px] text-slate-400 mb-5">Live from CRM — every lead is counted exactly once, grouped by its industry</p>
      <div className="space-y-4">
        {segments.map((s) => (
          <div key={s.industry}>
            <div className="flex items-center justify-between text-[13px] mb-1.5">
              <span className="font-medium text-[#111827]">{s.industry}</span>
              <span className="text-slate-500">
                <span className="font-mono">{s.count}</span> leads · <span className="font-mono">TZS {money(s.value)}k</span> pipeline · avg score <span className="font-mono">{s.avgScore}</span>
              </span>
            </div>
            <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
              <div className="h-full rounded-full btn-primary" style={{ width: `${(s.count / maxCount) * 100}%` }} />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* --------------------------------- BULK SMS -------------------------------- */

const SMS_CATEGORIES = ["General", "Debt Reminder", "Promotion", "Notification", "Greeting"];
const SMS_VARIABLES = ["{customer_name}", "{business_name}", "{amount}", "{balance}"];

// Templates and customer groups are real, genuine CRUD — matching the
// exact real pattern found in competitor evidence, variable placeholders
// and all. What's honestly not real, and won't pretend to be: actually
// delivering a message. That needs a real SMS gateway (Africa's Talking,
// Twilio, or similar) with real API credentials this build has never
// had — the identical honest boundary already drawn around WhatsApp's
// paid Business Platform (section 44). "Send" is disabled and says
// exactly why, rather than silently pretending to succeed.
function BulkSmsView({ crm }) {
  const [tab, setTab] = useState("groups");
  const templates = useCompanyTable("sms_templates", [], { mapRow: (r) => ({ id: r.id, dbId: r.id, name: r.name, category: r.category, message: r.message }) });
  const groups = useCompanyTable("sms_groups", [], { mapRow: (r) => ({ id: r.id, dbId: r.id, name: r.name, members: (r.sms_group_members || []).map((m) => ({ name: m.name, phone: m.phone })) }), select: "*,sms_group_members(*)" });
  const [showTemplateForm, setShowTemplateForm] = useState(false);
  const [showGroupForm, setShowGroupForm] = useState(false);
  const [templateForm, setTemplateForm] = useState({ name: "", category: "General", message: "" });
  const [groupName, setGroupName] = useState("");
  const [selectedLeads, setSelectedLeads] = useState(new Set());

  const smsCount = Math.ceil((templateForm.message.length || 1) / 160) || 1;

  async function saveTemplate(e) {
    e.preventDefault();
    if (!templateForm.name.trim() || !templateForm.message.trim()) return;
    const draft = { id: `TPL-${Date.now()}`, name: templateForm.name.trim(), category: templateForm.category, message: templateForm.message };
    templates.setRows((prev) => [draft, ...prev]);
    setShowTemplateForm(false);
    setTemplateForm({ name: "", category: "General", message: "" });
    notify("Template saved.");
    if (IS_CONFIGURED) {
      try {
        const header = await sb("sms_templates").insert({ name: draft.name, category: draft.category, message: draft.message }).single().run();
        if (header?.id) templates.setRows((prev) => prev.map((t) => (t.id === draft.id ? { ...t, dbId: header.id } : t)));
      } catch (_e) { notify("Saved locally, but the server update failed.", "error"); }
    }
  }

  async function saveGroup(e) {
    e.preventDefault();
    if (!groupName.trim() || selectedLeads.size === 0) return;
    const members = crm.rows.filter((l) => selectedLeads.has(l.id)).map((l) => ({ name: l.company, phone: l.phone }));
    const draft = { id: `GRP-${Date.now()}`, name: groupName.trim(), members };
    groups.setRows((prev) => [draft, ...prev]);
    setShowGroupForm(false);
    setGroupName("");
    setSelectedLeads(new Set());
    notify(`Group created: ${draft.name} (${members.length} members)`);
    if (IS_CONFIGURED) {
      try {
        const header = await sb("sms_groups").insert({ name: draft.name }).single().run();
        if (header?.id) {
          groups.setRows((prev) => prev.map((g) => (g.id === draft.id ? { ...g, dbId: header.id } : g)));
          if (members.length > 0) await sb("sms_group_members").insert(members.map((m) => ({ group_id: header.id, name: m.name, phone: m.phone }))).run();
        }
      } catch (_e) { notify("Saved locally, but the server update failed.", "error"); }
    }
  }

  return (
    <div className="space-y-4">
      <div className="rounded-xl p-5" style={{ background: "linear-gradient(135deg, #2563EB, #1D4ED8)" }}>
        <div className="flex items-start gap-2.5">
          <AlertCircle size={16} className="text-white/90 shrink-0 mt-0.5" />
          <p className="text-[12px] text-white/90 leading-relaxed">Templates and groups below are real. Actually sending a message needs a real SMS gateway connected — this build has no SMS provider credentials configured, so "Send" is disabled rather than pretending to succeed. Connect a provider like Africa&apos;s Talking or Twilio to enable real sending.</p>
        </div>
      </div>

      <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 w-fit">
        {[{ id: "groups", label: "Groups" }, { id: "templates", label: "Templates" }].map((t) => (
          <button key={t.id} onClick={() => setTab(t.id)} className={`text-[12px] font-medium px-3 py-1.5 rounded-md transition-colors ${tab === t.id ? "bg-white text-[#111827] shadow-sm" : "text-slate-500"}`}>{t.label}</button>
        ))}
      </div>

      {tab === "groups" && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-[12.5px] text-slate-500">{groups.rows.length} groups</p>
            <button onClick={() => setShowGroupForm(true)} className="btn-primary text-white text-[12.5px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5"><Plus size={14} /> Create Group</button>
          </div>
          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm divide-y divide-slate-50">
            {!groups.loading && groups.rows.length === 0 && <EmptyState icon={Users} title="No Customer Groups" hint="Create groups to organize customers for future bulk messaging." actionLabel="Create Group" onAction={() => setShowGroupForm(true)} />}
            {groups.loading && <p className="text-[12.5px] text-slate-400 text-center py-8">Loading...</p>}
            {groups.rows.map((g) => (
              <div key={g.id} className="flex items-center justify-between px-4 py-3.5">
                <div><p className="text-[13px] font-medium text-[#111827]">{g.name}</p><p className="text-[11px] text-slate-400">{g.members.length} members</p></div>
                <button disabled title="Requires a connected SMS gateway" className="text-[12px] font-medium text-slate-300 cursor-not-allowed flex items-center gap-1"><Send size={13} /> Send</button>
              </div>
            ))}
          </div>
        </div>
      )}

      {tab === "templates" && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-[12.5px] text-slate-500">{templates.rows.length} templates</p>
            <button onClick={() => setShowTemplateForm(true)} className="btn-primary text-white text-[12.5px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5"><Plus size={14} /> Create Template</button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {!templates.loading && templates.rows.length === 0 && <div className="col-span-full bg-white rounded-xl border border-slate-200/80 shadow-sm"><EmptyState icon={FileText} title="No templates" hint="Save a reusable message template with variable placeholders." actionLabel="Create Template" onAction={() => setShowTemplateForm(true)} /></div>}
            {templates.loading && <p className="col-span-full text-[12.5px] text-slate-400 text-center py-8">Loading...</p>}
            {templates.rows.map((t) => (
              <div key={t.id} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
                <div className="flex items-center justify-between mb-1.5"><p className="text-[13px] font-medium text-[#111827]">{t.name}</p><span className="text-[10px] font-medium px-1.5 py-0.5 rounded-full bg-slate-100 text-slate-500">{t.category}</span></div>
                <p className="text-[12px] text-slate-500 line-clamp-2">{t.message}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {showGroupForm && (
        <div className="fixed inset-0 z-40 flex justify-end">
          <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={() => setShowGroupForm(false)} />
          <form onSubmit={saveGroup} className="relative w-full sm:w-[400px] bg-white h-full shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
            <div className="px-6 pt-6 pb-5 border-b border-slate-100 flex items-start justify-between">
              <h2 className="text-[18px] font-semibold text-[#111827]">Create Group</h2>
              <button type="button" onClick={() => setShowGroupForm(false)} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
            </div>
            <div className="px-6 py-5 flex-1 space-y-4">
              <FormField label="Group name" required><input className={inputClass} value={groupName} onChange={(e) => setGroupName(e.target.value)} placeholder="e.g. Wholesale customers" /></FormField>
              <div>
                <label className="text-[12px] font-medium text-slate-600 block mb-1.5">Select real customers from CRM ({selectedLeads.size} selected)</label>
                <div className="max-h-64 overflow-y-auto border border-slate-100 rounded-lg divide-y divide-slate-50">
                  {crm.rows.filter((l) => l.phone).map((l) => (
                    <label key={l.id} className="flex items-center gap-2.5 px-3 py-2.5 cursor-pointer hover:bg-slate-50">
                      <input type="checkbox" checked={selectedLeads.has(l.id)} onChange={(e) => setSelectedLeads((prev) => { const next = new Set(prev); if (e.target.checked) next.add(l.id); else next.delete(l.id); return next; })} />
                      <div className="min-w-0"><p className="text-[12.5px] text-[#111827] truncate">{l.company}</p><p className="text-[10.5px] text-slate-400">{l.phone}</p></div>
                    </label>
                  ))}
                  {crm.rows.filter((l) => l.phone).length === 0 && <p className="text-[11.5px] text-slate-400 text-center py-4">No CRM leads with a phone number yet.</p>}
                </div>
              </div>
            </div>
            <div className="px-6 py-4 border-t border-slate-100 flex gap-2">
              <button type="button" onClick={() => setShowGroupForm(false)} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5">Cancel</button>
              <button type="submit" className="flex-1 text-[12px] font-medium btn-primary text-white rounded-lg py-2.5">Create Group</button>
            </div>
          </form>
        </div>
      )}

      {showTemplateForm && (
        <div className="fixed inset-0 z-40 flex justify-end">
          <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={() => setShowTemplateForm(false)} />
          <form onSubmit={saveTemplate} className="relative w-full sm:w-[400px] bg-white h-full shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
            <div className="px-6 pt-6 pb-5 border-b border-slate-100 flex items-start justify-between">
              <h2 className="text-[18px] font-semibold text-[#111827]">Create Template</h2>
              <button type="button" onClick={() => setShowTemplateForm(false)} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
            </div>
            <div className="px-6 py-5 flex-1 space-y-4">
              <FormField label="Template name" required><input className={inputClass} value={templateForm.name} onChange={(e) => setTemplateForm((f) => ({ ...f, name: e.target.value }))} /></FormField>
              <div>
                <label className="text-[12px] font-medium text-slate-600 block mb-1.5">Category</label>
                <div className="flex flex-wrap gap-2">
                  {SMS_CATEGORIES.map((c) => (
                    <button key={c} type="button" onClick={() => setTemplateForm((f) => ({ ...f, category: c }))} className={`text-[12px] font-medium px-3 py-1.5 rounded-full border transition-colors ${templateForm.category === c ? "border-[#2563EB]/50 bg-[#2563EB]/10 text-[#2563EB]" : "border-slate-200 text-slate-500"}`}>{c}</button>
                  ))}
                </div>
              </div>
              <FormField label="Message content" required><textarea className={inputClass} rows={5} value={templateForm.message} onChange={(e) => setTemplateForm((f) => ({ ...f, message: e.target.value }))} placeholder="Type your template message here..." /></FormField>
              <div className="flex flex-wrap gap-2">
                {SMS_VARIABLES.map((v) => (
                  <button key={v} type="button" onClick={() => setTemplateForm((f) => ({ ...f, message: f.message + v }))} className="text-[11px] font-mono px-2 py-1 rounded-md bg-slate-100 text-slate-500 hover:bg-slate-200">{v}</button>
                ))}
              </div>
              <p className="text-[11px] text-slate-400">{templateForm.message.length} characters · {smsCount}/{smsCount} SMS</p>
            </div>
            <div className="px-6 py-4 border-t border-slate-100 flex gap-2">
              <button type="button" onClick={() => setShowTemplateForm(false)} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5">Cancel</button>
              <button type="submit" className="flex-1 text-[12px] font-medium btn-primary text-white rounded-lg py-2.5">Create Template</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

/* ----------------------------------- POS -------------------------------------- */

const POS_TABS = [
  { id: "checkout", label: "Checkout", icon: ShoppingBag },
  { id: "history", label: "Register History", icon: Receipt },
];

// POS Shifts & Cash Drawer — the control a till cannot run without, and
// the one real gap a competitive audit exposed. Expected cash is COMPUTED
// (opening float + cash sales + pay-ins - pay-outs); counted cash is what
// a human physically finds in the drawer; the variance between them is
// the entire point. Both directions matter and the UI says so: short can
// be theft or a miskeyed sale, over means a customer was overcharged or a
// sale never rung. One shift open at a time, so attributing sales by
// timestamp is unambiguous rather than a guess.
function PosShiftPanel({ transactions, currentUser }) {
  const [now, setNow] = useState(new Date());
  useEffect(() => { const t = setInterval(() => setNow(new Date()), 30000); return () => clearInterval(t); }, []);
  const shifts = useCompanyTable("pos_shifts", [], { order: { col: "opened_at", ascending: false }, mapRow: (r) => ({ id: r.id, dbId: r.id, cashier: r.cashier, openingFloat: Number(r.opening_float) || 0, countedCash: r.counted_cash === null || r.counted_cash === undefined ? null : Number(r.counted_cash), status: r.status, openedAt: r.opened_at, closedAt: r.closed_at }) });
  const moves = useCompanyTable("pos_cash_movements", [], { order: { col: "created_at", ascending: false }, mapRow: (r) => ({ id: r.id, dbId: r.id, shiftId: r.shift_id, kind: r.kind, amount: Number(r.amount) || 0, reason: r.reason || "" }) });
  const [floatDraft, setFloatDraft] = useState("");
  const [countDraft, setCountDraft] = useState("");
  const [move, setMove] = useState({ kind: "Pay In", amount: "", reason: "" });

  const open = shifts.rows.find((s) => s.status === "Open");
  const valueOf = (t) => (t.items || []).reduce((s, it) => s + it.qty * it.price, 0);

  const sales = useMemo(() => {
    if (!open) return { count: 0, gross: 0, cash: 0, other: 0 };
    const rows = transactions.rows.filter((t) => t.createdAt && t.createdAt >= open.openedAt);
    const cash = rows.filter((t) => t.method === "Cash").reduce((s, t) => s + valueOf(t), 0);
    const gross = rows.reduce((s, t) => s + valueOf(t), 0);
    return { count: rows.length, gross, cash, other: gross - cash };
  }, [transactions.rows, open]);

  const mine = open ? moves.rows.filter((m) => m.shiftId === (open.dbId || open.id)) : [];
  const payIns = mine.filter((m) => m.kind === "Pay In").reduce((s, m) => s + m.amount, 0);
  const payOuts = mine.filter((m) => m.kind === "Pay Out").reduce((s, m) => s + m.amount, 0);
  const expected = open ? open.openingFloat + sales.cash + payIns - payOuts : 0;
  const counted = Number(countDraft);
  const variance = countDraft.trim() === "" || isNaN(counted) ? null : counted - expected;

  async function openShift() {
    const f = Number(floatDraft);
    if (isNaN(f) || f < 0) { notify("Enter the counted opening float.", "error"); return; }
    if (open) { notify("A shift is already open — close it first. One drawer, one shift.", "error"); return; }
    const row = { id: `SH-${Date.now()}`, cashier: currentUser?.name || "Cashier", openingFloat: f, countedCash: null, status: "Open", openedAt: new Date().toISOString(), closedAt: null };
    shifts.setRows((prev) => [row, ...prev]);
    setFloatDraft("");
    notify(`Shift opened by ${row.cashier} — float TZS ${money(f)}k.`);
    if (IS_CONFIGURED) {
      try {
        const header = await sb("pos_shifts").insert({ cashier: row.cashier, opening_float: f, status: "Open", opened_at: row.openedAt }).single().run();
        if (header?.id) shifts.setRows((prev) => prev.map((s) => (s.id === row.id ? { ...s, dbId: header.id } : s)));
      } catch (_e) { notify("Opened locally, but the server update failed.", "error"); }
    }
  }

  async function addMove() {
    const amt = Number(move.amount);
    if (!open || isNaN(amt) || amt <= 0) { notify("Enter an amount above zero.", "error"); return; }
    const row = { id: `CM-${Date.now()}`, shiftId: open.dbId || open.id, kind: move.kind, amount: amt, reason: move.reason.trim() };
    moves.setRows((prev) => [row, ...prev]);
    setMove({ kind: move.kind, amount: "", reason: "" });
    notify(`${row.kind} of TZS ${money(amt)}k recorded — expected cash updated.`);
    if (IS_CONFIGURED && open.dbId) {
      try { await sb("pos_cash_movements").insert({ shift_id: open.dbId, kind: row.kind, amount: amt, reason: row.reason || null }).run(); } catch (_e) { notify("Recorded locally, but the server update failed.", "error"); }
    }
  }

  async function closeShift() {
    if (!open || variance === null) { notify("Count the drawer first — a shift closed without a count proves nothing.", "error"); return; }
    const closedAt = new Date().toISOString();
    const verdict = variance === 0 ? "balanced exactly" : variance < 0 ? `SHORT by TZS ${money(Math.abs(variance))}k` : `OVER by TZS ${money(variance)}k`;
    shifts.setRows((prev) => prev.map((s) => (s.id === open.id ? { ...s, status: "Closed", countedCash: counted, closedAt } : s)));
    notify(`Shift closed — drawer ${verdict}.`, variance === 0 ? "success" : "error");
    logAudit("POS shift closed", "Point of Sale", `${open.cashier}: expected ${money(Math.round(expected))}k, counted ${money(counted)}k — ${verdict}`, currentUser?.name || "Cashier");
    setCountDraft("");
    if (IS_CONFIGURED && open.dbId) {
      try { await sb("pos_shifts").eq("id", open.dbId).update({ status: "Closed", counted_cash: counted, closed_at: closedAt }).run(); } catch (_e) { notify("Closed locally, but the server update failed.", "error"); }
    }
  }

  const Row = ({ label, value, strong }) => (
    <div className={`flex items-center justify-between py-1.5 ${strong ? "border-t border-slate-200 mt-1 pt-2" : ""}`}>
      <span className={`text-[12px] ${strong ? "font-semibold text-[#111827]" : "text-slate-500"}`}>{label}</span>
      <span className={`text-[12.5px] font-mono ${strong ? "font-bold text-[#111827]" : "text-slate-600"}`}>{value}</span>
    </div>
  );

  if (!open) {
    const last = shifts.rows.find((s) => s.status === "Closed");
    const lastVar = last && last.countedCash !== null ? null : null;
    return (
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 mb-4">
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <div>
            <p className="text-[13.5px] font-semibold text-[#111827]">No shift open</p>
            <p className="text-[11px] text-slate-400">Count the drawer and open a shift before selling — sales rung with no shift open are recorded, but reconcile to nothing.</p>
          </div>
          <div className="flex gap-2 items-center shrink-0">
            <input type="number" min="0" className={inputClass + " w-36"} value={floatDraft} onChange={(e) => setFloatDraft(e.target.value)} placeholder="Opening float (TZS k)" />
            <button onClick={openShift} className="btn-primary text-white text-[12px] font-medium rounded-lg px-3.5 py-2 shrink-0">Open Shift</button>
          </div>
        </div>
        {last && <p className="text-[10.5px] text-slate-400 mt-2.5 pt-2.5 border-t border-slate-100">Last shift: {last.cashier} · closed {(last.closedAt || "").slice(0, 16).replace("T", " ")} · counted TZS {money(last.countedCash ?? 0)}k</p>}
      </div>
    );
  }

  const mins = Math.max(0, Math.round((now - new Date(open.openedAt)) / 60000));
  return (
    <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 mb-4">
      <div className="flex items-center justify-between gap-3 flex-wrap mb-3">
        <div className="flex items-center gap-2">
          <span className="w-2 h-2 rounded-full bg-[#16A34A] animate-pulse" />
          <p className="text-[13.5px] font-semibold text-[#111827]">Shift open — {open.cashier}</p>
          <span className="text-[11px] text-slate-400">{Math.floor(mins / 60)}h {mins % 60}m</span>
        </div>
        <button onClick={closeShift} className="text-[12px] font-medium bg-[#F59E0B] text-white rounded-lg px-3.5 py-2 shrink-0">Close Shift &amp; Reconcile</button>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-3">
        <div><p className="text-[10.5px] text-slate-400">Transactions</p><p className="text-[15px] font-mono font-bold text-[#111827]">{sales.count}</p></div>
        <div><p className="text-[10.5px] text-slate-400">Total Sales</p><p className="text-[15px] font-mono font-bold text-[#111827]">{money(Math.round(sales.gross))}k</p></div>
        <div><p className="text-[10.5px] text-slate-400">Cash Sales</p><p className="text-[15px] font-mono font-bold text-[#16A34A]">{money(Math.round(sales.cash))}k</p></div>
        <div><p className="text-[10.5px] text-slate-400">Non-cash Sales</p><p className="text-[15px] font-mono font-bold text-slate-500">{money(Math.round(sales.other))}k</p></div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 pt-3 border-t border-slate-100">
        <div>
          <p className="text-[12px] font-semibold text-[#111827] mb-1">Cash Drawer</p>
          <Row label="Opening float" value={`${money(open.openingFloat)}k`} />
          <Row label="+ Cash sales" value={`${money(Math.round(sales.cash))}k`} />
          <Row label="+ Pay ins" value={`${money(payIns)}k`} />
          <Row label="− Pay outs" value={`${money(payOuts)}k`} />
          <Row label="Expected in drawer" value={`TZS ${money(Math.round(expected))}k`} strong />
          <div className="flex gap-2 items-center mt-2.5">
            <input type="number" className={inputClass} value={countDraft} onChange={(e) => setCountDraft(e.target.value)} placeholder="Counted cash (TZS k)" />
          </div>
          {variance !== null && (
            <div className="mt-2 rounded-lg px-3 py-2" style={{ backgroundColor: variance === 0 ? "#DCFCE7" : variance < 0 ? "#FEE2E2" : "#FEF3C7" }}>
              <p className="text-[12px] font-semibold" style={{ color: variance === 0 ? "#16A34A" : variance < 0 ? "#EF4444" : "#92400E" }}>
                {variance === 0 ? "Balanced exactly." : variance < 0 ? `SHORT by TZS ${money(Math.abs(variance))}k` : `OVER by TZS ${money(variance)}k`}
              </p>
              {variance !== 0 && <p className="text-[10px] mt-0.5" style={{ color: variance < 0 ? "#991B1B" : "#92400E" }}>{variance < 0 ? "Money left the till without a sale — or a sale was miskeyed." : "Over is not good news: a customer was likely overcharged, or a sale never got rung."}</p>}
            </div>
          )}
        </div>

        <div>
          <p className="text-[12px] font-semibold text-[#111827] mb-1">Pay In / Pay Out</p>
          <p className="text-[10.5px] text-slate-400 mb-2">Any money crossing the till that is not a sale — a float top-up, petty cash, or a refund paid out from an earlier shift. Without these, expected cash is a lie the moment anyone opens the drawer.</p>
          <div className="flex flex-wrap gap-2">
            <select className={inputClass + " max-w-[110px]"} value={move.kind} onChange={(e) => setMove({ ...move, kind: e.target.value })}>
              <option>Pay In</option><option>Pay Out</option>
            </select>
            <input type="number" min="0" className={inputClass + " max-w-[110px]"} value={move.amount} onChange={(e) => setMove({ ...move, amount: e.target.value })} placeholder="TZS k" />
            <input className={inputClass + " flex-1 min-w-[120px]"} value={move.reason} onChange={(e) => setMove({ ...move, reason: e.target.value })} placeholder="Reason" />
            <button onClick={addMove} className="btn-primary text-white text-[12px] font-medium rounded-lg px-3 py-2 shrink-0">Record</button>
          </div>
          {mine.length > 0 && (
            <div className="mt-2.5 space-y-1">
              {mine.slice(0, 4).map((m) => (
                <div key={m.id} className="flex justify-between text-[11.5px]">
                  <span className="text-slate-500 truncate">{m.kind}{m.reason ? ` · ${m.reason}` : ""}</span>
                  <span className={`font-mono shrink-0 ml-2 ${m.kind === "Pay In" ? "text-[#16A34A]" : "text-[#EF4444]"}`}>{m.kind === "Pay In" ? "+" : "−"}{money(m.amount)}k</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function POS({ inventory, transactionsHook, company, currentUser }) {
  const [tab, setTab] = useState("checkout");
  const transactions = transactionsHook;

  const todayStr = TODAY.toISOString().slice(0, 10);
  const stats = useMemo(() => {
    const today = transactions.rows.filter((t) => t.date === todayStr);
    const revenue = today.reduce((s, t) => s + t.items.reduce((si, it) => si + it.qty * it.price, 0) * (1 + TAX_RATE), 0);
    const itemsSold = today.reduce((s, t) => s + t.items.reduce((si, it) => si + it.qty, 0), 0);
    return { count: today.length, revenue, itemsSold, avg: today.length ? revenue / today.length : 0 };
  }, [transactions.rows, todayStr]);

  const POS_KPIS = [
    { label: "Today's Sales", value: `TZS ${money(Math.round(stats.revenue))}k`, delta: "Incl. VAT", up: true, icon: CircleDollarSign },
    { label: "Transactions", value: String(stats.count), delta: "Today", up: true, icon: Receipt },
    { label: "Items Sold", value: String(stats.itemsSold), delta: "Today", up: true, icon: ShoppingBag },
    { label: "Avg Basket", value: `TZS ${money(Math.round(stats.avg))}k`, delta: "Per sale today", up: true, icon: Percent },
  ];

  return (
    <div className="space-y-5">
      <PosShiftPanel transactions={transactions} currentUser={currentUser} />
      <div>
        <h1 className="text-[20px] sm:text-[22px] font-semibold text-[#111827] tracking-tight">Point of Sale</h1>
        <p className="text-[13px] text-slate-500 mt-1">Counter checkout, priced and stocked from live Inventory</p>
      </div>

      <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 overflow-x-auto w-fit max-w-full">
        {POS_TABS.map((t) => {
          const Icon = t.icon;
          const isActive = tab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`text-[12px] font-medium px-3 py-1.5 rounded-md flex items-center gap-1.5 whitespace-nowrap transition-colors ${
                isActive ? "bg-white text-[#111827] shadow-sm" : "text-slate-500 hover:text-slate-700"
              }`}
            >
              <Icon size={13} /> {t.label}
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {POS_KPIS.map((k) => <KpiCard key={k.label} item={k} />)}
      </div>

      {tab === "checkout" && <Checkout inventory={inventory} transactions={transactions} company={company} />}
      {tab === "history" && <RegisterHistory transactions={transactions} inventory={inventory} company={company} />}
    </div>
  );
}

function Checkout({ inventory, transactions, company }) {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [cart, setCart] = useState([]); // [{ sku, name, price, qty }]
  const [method, setMethod] = useState("Cash");
  const [receipt, setReceipt] = useState(null);
  const [busy, setBusy] = useState(false);

  // POS sells the same physical stock Inventory tracks, priced with the
  // same retail markup the storefront uses — one product, one price,
  // regardless of which counter it's sold from.
  const products = useMemo(
    () => inventory.rows.map((it) => ({ ...it, price: Math.round(it.unitCost * MARKUP) })),
    [inventory.rows]
  );
  const categories = useMemo(() => [...new Set(products.map((p) => p.category))], [products]);

  const filtered = useMemo(() => {
    return products.filter((p) => {
      const matchesCat = category === "all" || p.category === category;
      const matchesQ = !query.trim() || p.name.toLowerCase().includes(query.toLowerCase()) || p.sku.toLowerCase().includes(query.toLowerCase());
      return matchesCat && matchesQ;
    });
  }, [products, category, query]);

  function addToCart(item) {
    const stock = inventory.rows.find((it) => it.sku === item.sku)?.qty || 0;
    setCart((prev) => {
      const existing = prev.find((c) => c.sku === item.sku);
      if (existing) {
        if (existing.qty >= stock) {
          notify(`Only ${stock} ${item.unit} of ${item.name} in stock`, "error");
          return prev;
        }
        return prev.map((c) => (c.sku === item.sku ? { ...c, qty: c.qty + 1 } : c));
      }
      if (stock <= 0) {
        notify(`${item.name} is out of stock`, "error");
        return prev;
      }
      return [...prev, { sku: item.sku, name: item.name, price: item.price, qty: 1, unit: item.unit }];
    });
  }

  function changeQty(sku, delta) {
    setCart((prev) => prev
      .map((c) => (c.sku === sku ? { ...c, qty: c.qty + delta } : c))
      .filter((c) => c.qty > 0));
  }

  const subtotal = cart.reduce((s, c) => s + c.qty * c.price, 0);
  const tax = Math.round(subtotal * TAX_RATE);
  const total = subtotal + tax;

  async function completeSale() {
    if (cart.length === 0 || busy) return;

    // Final stock-sufficiency check against live Inventory right before
    // committing — the cart could have gone stale if stock moved elsewhere
    // (a sales order fulfilled, a work order completed) while shopping.
    const shortages = cart.filter((c) => {
      const stock = inventory.rows.find((it) => it.sku === c.sku)?.qty || 0;
      return c.qty > stock;
    });
    if (shortages.length) {
      notify(`Not enough stock for: ${shortages.map((s) => s.name).join(", ")}`, "error");
      return;
    }

    setBusy(true);
    const draft = { id: docId("POS"), cashier: currentUser?.name || "You", method, date: TODAY.toISOString().slice(0, 10), createdAt: new Date().toISOString(), items: cart.map((c) => ({ sku: c.sku, name: c.name, qty: c.qty, price: c.price })), returns: [] };

    // Deduct sold quantities from the shared Inventory table immediately —
    // the same table Inventory, Manufacturing, and Sales all read.
    inventory.setRows((prev) => prev.map((it) => {
      const line = cart.find((c) => c.sku === it.sku);
      return line ? { ...it, qty: Math.max(0, it.qty - line.qty) } : it;
    }));
    transactions.setRows((prev) => [draft, ...prev]);

    if (IS_CONFIGURED) {
      try {
        const header = await sb("pos_transactions").insert({
          doc_number: draft.id, payment_method: method, subtotal, tax, total,
        }).single().run();
        if (header?.id) {
          await sb("pos_transaction_items").insert(
            cart.map((c) => ({ transaction_id: header.id, item_name: c.name, item_sku: c.sku, qty: c.qty, price: c.price }))
          ).run();
          transactions.setRows((prev) => prev.map((t) => (t.id === draft.id ? { ...t, dbId: header.id } : t)));
        }
        for (const c of cart) {
          const item = inventory.rows.find((it) => it.sku === c.sku);
          const newQty = Math.max(0, (item?.qty || 0) - c.qty);
          await sb("inventory_items").eq("sku", c.sku).update({ qty_on_hand: newQty }).run();
          await sb("inventory_stock_movements").insert({ item_id: c.sku, movement: "Out", qty: c.qty, reference: `${draft.id} sale` }).run();
        }
      } catch (e) {
        notify("Sale completed locally, but saving to the server failed.", "error");
      }
    }

    notify(`Sale complete — TZS ${money(total)}k`);
    setReceipt({ ...draft, subtotal, tax, total });
    setCart([]);
    setBusy(false);
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-[1fr_360px] gap-5 items-start">
      {/* Product picker */}
      <div className="space-y-4 min-w-0">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 overflow-x-auto">
            <button
              onClick={() => setCategory("all")}
              className={`text-[12px] font-medium px-3 py-1.5 rounded-md whitespace-nowrap transition-colors ${category === "all" ? "bg-white text-[#111827] shadow-sm" : "text-slate-500"}`}
            >
              All
            </button>
            {categories.map((c) => (
              <button
                key={c}
                onClick={() => setCategory(c)}
                className={`text-[12px] font-medium px-3 py-1.5 rounded-md whitespace-nowrap transition-colors ${category === c ? "bg-white text-[#111827] shadow-sm" : "text-slate-500"}`}
              >
                {c}
              </button>
            ))}
          </div>
          <div className="relative w-full sm:w-64">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search or scan SKU..."
              className="w-full bg-white border border-slate-200 rounded-lg pl-8 pr-3 py-2 text-[13px] outline-none focus:border-[#16A34A] focus:ring-1 focus:ring-[#16A34A]/30 transition-all"
            />
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-3">
          {filtered.map((p) => {
            const status = stockStatus(p.qty, p.reorder);
            const outOfStock = status === "Out of Stock";
            return (
              <button
                key={p.sku}
                onClick={() => addToCart(p)}
                disabled={outOfStock}
                className={`text-left bg-white rounded-xl border border-slate-200/80 shadow-sm p-3.5 transition-all ${
                  outOfStock ? "opacity-40 cursor-not-allowed" : "hover:border-[#16A34A]/50 hover:shadow-md hover:-translate-y-0.5"
                }`}
              >
                <div
                  className="h-16 rounded-lg mb-2.5 flex items-center justify-center"
                  style={{ background: CATEGORY_GRADIENT[p.category] || "linear-gradient(135deg, #111827, #16A34A)" }}
                >
                  <Package size={20} strokeWidth={1.5} className="text-white/85" />
                </div>
                <p className="text-[12.5px] font-medium text-[#111827] leading-snug line-clamp-2 min-h-[32px]">{p.name}</p>
                <div className="flex items-center justify-between mt-2">
                  <span className="text-[13px] font-mono font-semibold text-[#111827]">{money(p.price)}k</span>
                  <span className="text-[10.5px] text-slate-400 font-mono">{outOfStock ? "0 left" : `${p.qty} left`}</span>
                </div>
              </button>
            );
          })}
          {filtered.length === 0 && (
            <div className="col-span-full bg-white rounded-xl border border-slate-200/80 shadow-sm">
              <EmptyState icon={Search} title="No products found" hint="Try a different search term or category." />
            </div>
          )}
        </div>
      </div>

      {/* Cart */}
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5 lg:sticky lg:top-0 flex flex-col">
        <h3 className="text-[14px] font-semibold text-[#111827] mb-3 flex items-center gap-2">
          <ShoppingBag size={15} /> Current Sale
        </h3>

        {cart.length === 0 ? (
          <p className="text-[12.5px] text-slate-400 py-8 text-center">Tap a product to add it to the sale.</p>
        ) : (
          <div className="space-y-2.5 mb-4 max-h-[320px] overflow-y-auto">
            {cart.map((c) => (
              <div key={c.sku} className="flex items-center gap-2.5">
                <div className="flex-1 min-w-0">
                  <p className="text-[12.5px] font-medium text-[#111827] truncate">{c.name}</p>
                  <p className="text-[11px] text-slate-400 font-mono">{money(c.price)}k each</p>
                </div>
                <div className="flex items-center gap-1.5 shrink-0">
                  <button onClick={() => changeQty(c.sku, -1)} aria-label={`Decrease ${c.name} quantity`} className="w-6 h-6 rounded-md border border-slate-200 flex items-center justify-center text-slate-500 hover:bg-slate-50">
                    <Minus size={11} />
                  </button>
                  <span className="text-[12.5px] font-mono w-5 text-center">{c.qty}</span>
                  <button onClick={() => changeQty(c.sku, 1)} aria-label={`Increase ${c.name} quantity`} className="w-6 h-6 rounded-md border border-slate-200 flex items-center justify-center text-slate-500 hover:bg-slate-50">
                    <Plus size={11} />
                  </button>
                </div>
                <span className="text-[12.5px] font-mono text-[#111827] w-14 text-right shrink-0">{money(c.qty * c.price)}k</span>
              </div>
            ))}
          </div>
        )}

        <div className="border-t border-slate-100 pt-3 space-y-1.5 text-[12.5px] mb-4">
          <div className="flex justify-between text-slate-500"><span>Subtotal</span><span className="font-mono">TZS {money(subtotal)}k</span></div>
          <div className="flex justify-between text-slate-500"><span>VAT ({Math.round(TAX_RATE * 100)}%)</span><span className="font-mono">TZS {money(tax)}k</span></div>
          <div className="flex justify-between text-[#111827] font-semibold text-[14px] pt-1.5 border-t border-slate-100"><span>Total</span><span className="font-mono">TZS {money(total)}k</span></div>
        </div>

        <div className="mb-4">
          <p className="text-[11px] font-medium text-slate-500 mb-2">Payment method</p>
          <div className="grid grid-cols-3 gap-1.5">
            {POS_PAYMENT_METHODS.map((m) => {
              const Icon = m === "Cash" ? Banknote : m === "Card" ? CreditCard : Smartphone;
              return (
                <button
                  key={m}
                  onClick={() => setMethod(m)}
                  className={`flex flex-col items-center gap-1 text-[10.5px] font-medium rounded-lg py-2 border transition-colors ${
                    method === m ? "border-[#16A34A] bg-[#16A34A]/8 text-[#111827]" : "border-slate-200 text-slate-500 hover:bg-slate-50"
                  }`}
                >
                  <Icon size={15} /> {m}
                </button>
              );
            })}
          </div>
        </div>

        <button
          onClick={completeSale}
          disabled={cart.length === 0 || busy}
          className="btn-primary text-white text-[13px] font-semibold rounded-lg py-3 disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {busy ? "Processing..." : `Complete Sale · TZS ${money(total)}k`}
        </button>
      </div>

      {receipt && <ReceiptPanel receipt={receipt} onClose={() => setReceipt(null)} company={company} />}
    </div>
  );
}

function ReceiptPanel({ receipt, onClose, allowReturn, onOpenReturn, company }) {
  const returns = receipt.returns || [];
  const refunded = returns.reduce((s, r) => s + r.refundTotal, 0);
  const fullyReturned = receipt.items.every((it) => {
    const returnedQty = returns.reduce((s, r) => s + (r.items.find((ri) => ri.sku === it.sku)?.qty || 0), 0);
    return returnedQty >= it.qty;
  });

  // A real bug fixed here, not just a new feature added: this button had
  // no onClick handler at all before this pass — clicking "Print
  // Receipt" did nothing, silently. Fixed with a genuine print function
  // that opens a real, separate print document sized to the company's
  // actual configured receipt width (58mm, 80mm, or A4) rather than
  // printing whatever happens to be on screen, honoring the real
  // header/footer/logo preferences set in Settings.
  function printReceipt() {
    const width = company?.receiptWidth || "80mm";
    const showLogo = company?.receiptShowLogo !== false;
    const footer = company?.receiptFooter || "Thank you for your business!";
    const win = window.open("", "_blank", "width=400,height=600");
    if (!win) { notify("Pop-up blocked — allow pop-ups to print receipts.", "error"); return; }
    const itemRows = receipt.items.map((it) => `<div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span>${it.qty}× ${it.name}</span><span>${money(it.qty * it.price)}k</span></div>`).join("");
    win.document.write(`
      <html><head><title>Receipt ${receipt.id}</title>
      <style>
        body { font-family: monospace; padding: 12px; max-width: ${width === "A4" ? "210mm" : width}; margin: 0 auto; font-size: ${width === "58mm" ? "10px" : "12px"}; }
        h2 { text-align: center; margin: 4px 0; }
        hr { border: none; border-top: 1px dashed #999; margin: 8px 0; }
        .total { display:flex; justify-content:space-between; font-weight:bold; margin-top: 6px; }
        .footer { text-align:center; margin-top: 14px; font-size: 0.9em; }
      </style></head>
      <body>
        ${showLogo ? "<h2>" + (company?.name || "Receipt") + "</h2>" : ""}
        <p style="text-align:center;margin:0;">${receipt.id} · ${TODAY.toISOString().slice(0, 10)}</p>
        <hr />
        ${itemRows}
        <hr />
        <div class="total"><span>Total</span><span>TZS ${money(receipt.total)}k</span></div>
        <div class="footer">${footer}</div>
      </body></html>
    `);
    win.document.close();
    win.focus();
    win.print();
  }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <div className="relative w-full sm:w-[380px] bg-white h-full shadow-2xl p-6 overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="flex items-start justify-between mb-6">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-lg flex items-center justify-center" style={{ backgroundColor: "#16A34A14" }}>
              <CheckCircle2 size={18} className="text-[#16A34A]" />
            </div>
            <div>
              <p className="text-[11px] text-slate-400 font-mono">{receipt.id}</p>
              <h2 className="text-[16px] font-semibold text-[#111827]">{allowReturn ? "Receipt" : "Sale Complete"}</h2>
            </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close">
            <X size={18} />
          </button>
        </div>

        {fullyReturned && (
          <span className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5 mb-4 w-fit" style={{ backgroundColor: "#EF444414", color: "#EF4444" }}>
            <span className="w-1.5 h-1.5 rounded-full bg-[#EF4444]" /> Fully returned
          </span>
        )}

        <div className="border border-slate-100 rounded-lg overflow-hidden mb-5">
          {receipt.items.map((it, i) => (
            <div key={i} className={`flex items-center justify-between px-3 py-2.5 text-[13px] ${i !== receipt.items.length - 1 ? "border-b border-slate-50" : ""}`}>
              <div>
                <p className="text-slate-700">{it.name}</p>
                <p className="text-[11px] text-slate-400 font-mono">{it.qty} × TZS {money(it.price)}k</p>
              </div>
              <span className="font-mono text-[#111827]">{money(it.qty * it.price)}k</span>
            </div>
          ))}
        </div>

        <div className="space-y-1.5 text-[13px] mb-6">
          <div className="flex justify-between text-slate-500"><span>Subtotal</span><span className="font-mono">TZS {money(receipt.subtotal)}k</span></div>
          <div className="flex justify-between text-slate-500"><span>VAT ({Math.round(TAX_RATE * 100)}%)</span><span className="font-mono">TZS {money(receipt.tax)}k</span></div>
          <div className="flex justify-between text-[#111827] font-semibold text-[14px] pt-1.5 border-t border-slate-100"><span>Total Paid</span><span className="font-mono">TZS {money(receipt.total)}k</span></div>
          {refunded > 0 && (
            <div className="flex justify-between text-[#EF4444] font-medium pt-1"><span>Refunded</span><span className="font-mono">−{money(refunded)}k</span></div>
          )}
        </div>

        <div className="flex items-center gap-2.5 text-[13px] text-slate-600 mb-4">
          <Receipt size={14} className="text-slate-400" /> Paid via {receipt.method}
        </div>

        {returns.length > 0 && (
          <div className="mb-4">
            <p className="text-[11px] text-slate-400 mb-2 uppercase tracking-wide">Returns</p>
            <div className="border border-slate-100 rounded-lg overflow-hidden">
              {returns.map((r) => (
                <div key={r.id} className="px-3 py-2.5 text-[13px] border-b border-slate-50 last:border-0">
                  <div className="flex items-center justify-between">
                    <p className="text-slate-700">{r.reason}</p>
                    <span className="font-mono text-[#EF4444]">−{money(r.refundTotal)}k</span>
                  </div>
                  <p className="text-[11px] text-slate-400 font-mono">{r.date} · {r.items.map((it) => `${it.qty}× ${it.name}`).join(", ")}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="flex-1" />

        <div className="flex flex-col gap-2">
          <button onClick={printReceipt} className="flex items-center justify-center gap-1.5 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50 transition-colors">
            <Printer size={13} /> Print Receipt
          </button>
          {allowReturn && !fullyReturned && (
            <button
              onClick={onOpenReturn}
              className="flex items-center justify-center gap-1.5 text-[12px] font-medium text-[#EF4444] border border-[#EF4444]/25 rounded-lg py-2.5 hover:bg-[#EF4444]/5 transition-colors"
            >
              <ArrowUpDown size={13} /> Process Return
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

function ReturnFormPanel({ transaction, onClose, onSubmit }) {
  // How much of each line item has already been returned, across every
  // prior return on this transaction — you can't return more than remains.
  const remaining = transaction.items.map((it) => {
    const alreadyReturned = (transaction.returns || []).reduce(
      (s, r) => s + (r.items.find((ri) => ri.sku === it.sku)?.qty || 0), 0
    );
    return { ...it, maxQty: it.qty - alreadyReturned };
  }).filter((it) => it.maxQty > 0);

  const [qtys, setQtys] = useState(() => Object.fromEntries(remaining.map((it) => [it.sku, 0])));
  const [reason, setReason] = useState(RETURN_REASONS[0]);

  function setQty(sku, val, max) {
    setQtys((q) => ({ ...q, [sku]: Math.max(0, Math.min(max, val)) }));
  }

  const returnItems = remaining.filter((it) => qtys[it.sku] > 0).map((it) => ({ sku: it.sku, name: it.name, qty: qtys[it.sku], price: it.price }));
  const refundSubtotal = returnItems.reduce((s, it) => s + it.qty * it.price, 0);
  const refundTotal = Math.round(refundSubtotal * (1 + TAX_RATE));
  const valid = returnItems.length > 0;

  return (
    <div className="fixed inset-0 z-40 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <div className="relative w-full sm:w-[400px] bg-white h-full shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-6 pt-6 pb-5 border-b border-slate-100 flex items-start justify-between">
          <div>
            <p className="text-[11px] text-slate-400 uppercase tracking-wide">{transaction.id}</p>
            <h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">Process Return</h2>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>

        <div className="px-6 py-5 flex-1 space-y-4">
          <div>
            <p className="text-[11px] font-medium text-slate-500 mb-2">Select items and quantities to return</p>
            <div className="space-y-2.5">
              {remaining.map((it) => (
                <div key={it.sku} className="flex items-center gap-2.5 border border-slate-100 rounded-lg p-2.5">
                  <div className="flex-1 min-w-0">
                    <p className="text-[12.5px] font-medium text-[#111827] truncate">{it.name}</p>
                    <p className="text-[11px] text-slate-400 font-mono">Up to {it.maxQty} returnable · {money(it.price)}k each</p>
                  </div>
                  <div className="flex items-center gap-1.5 shrink-0">
                    <button type="button" onClick={() => setQty(it.sku, qtys[it.sku] - 1, it.maxQty)} className="w-6 h-6 rounded-md border border-slate-200 flex items-center justify-center text-slate-500 hover:bg-slate-50" aria-label={`Decrease ${it.name} return quantity`}>
                      <Minus size={11} />
                    </button>
                    <span className="text-[12.5px] font-mono w-5 text-center">{qtys[it.sku]}</span>
                    <button type="button" onClick={() => setQty(it.sku, qtys[it.sku] + 1, it.maxQty)} className="w-6 h-6 rounded-md border border-slate-200 flex items-center justify-center text-slate-500 hover:bg-slate-50" aria-label={`Increase ${it.name} return quantity`}>
                      <Plus size={11} />
                    </button>
                  </div>
                </div>
              ))}
              {remaining.length === 0 && <p className="text-[12.5px] text-slate-400">Every item on this receipt has already been returned.</p>}
            </div>
          </div>

          <FormField label="Reason">
            <select className={inputClass} value={reason} onChange={(e) => setReason(e.target.value)}>
              {RETURN_REASONS.map((r) => <option key={r} value={r}>{r}</option>)}
            </select>
          </FormField>

          {valid && (
            <div className="bg-slate-50 rounded-lg p-3 space-y-1 text-[12.5px]">
              <div className="flex justify-between text-slate-500"><span>Refund subtotal</span><span className="font-mono">TZS {money(refundSubtotal)}k</span></div>
              <div className="flex justify-between text-slate-500"><span>VAT ({Math.round(TAX_RATE * 100)}%)</span><span className="font-mono">TZS {money(Math.round(refundSubtotal * TAX_RATE))}k</span></div>
              <div className="flex justify-between text-[#EF4444] font-semibold pt-1 border-t border-slate-200 mt-1"><span>Total refund</span><span className="font-mono">TZS {money(refundTotal)}k</span></div>
            </div>
          )}

          <p className="text-[11.5px] text-slate-400">Returned quantities are restocked to Inventory immediately.</p>
        </div>

        <div className="px-6 py-4 border-t border-slate-100 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50 transition-colors">Cancel</button>
          <button
            type="button"
            disabled={!valid}
            onClick={() => onSubmit({ items: returnItems, reason, refundTotal })}
            className="flex-1 text-[12px] font-medium bg-[#EF4444] text-white rounded-lg py-2.5 disabled:opacity-40 disabled:cursor-not-allowed"
          >
            Refund TZS {money(refundTotal)}k
          </button>
        </div>
      </div>
    </div>
  );
}

function RegisterHistory({ transactions, inventory, company }) {
  const [selected, setSelected] = useState(null);
  const [returning, setReturning] = useState(null);
  const { rows, setRows, loading } = transactions;

  async function processReturn(transaction, { items, reason, refundTotal }) {
    const returnRecord = { id: `RET-${Date.now()}`, items, reason, refundTotal, date: TODAY.toISOString().slice(0, 10) };

    // Restock returned quantities to the shared Inventory immediately.
    inventory.setRows((prev) => prev.map((it) => {
      const line = items.find((ri) => ri.sku === it.sku);
      return line ? { ...it, qty: it.qty + line.qty } : it;
    }));

    setRows((prev) => prev.map((t) => (t.id === transaction.id ? { ...t, returns: [returnRecord, ...(t.returns || [])] } : t)));
    setSelected((s) => (s && s.id === transaction.id ? { ...s, returns: [returnRecord, ...(s.returns || [])] } : s));
    setReturning(null);
    notify(`Return processed — TZS ${money(refundTotal)}k refunded, stock restocked`);

    if (IS_CONFIGURED && transaction.dbId) {
      try {
        const header = await sb("pos_returns").insert({
          transaction_id: transaction.dbId, reason, refund_total: refundTotal,
        }).single().run();
        if (header?.id) {
          await sb("pos_return_items").insert(
            items.map((it) => ({ return_id: header.id, item_name: it.name, item_sku: it.sku, qty: it.qty, price: it.price }))
          ).run();
        }
        for (const it of items) {
          const item = inventory.rows.find((i) => i.sku === it.sku);
          const newQty = (item?.qty || 0) + it.qty;
          await sb("inventory_items").eq("sku", it.sku).update({ qty_on_hand: newQty }).run();
          await sb("inventory_stock_movements").insert({ item_id: it.sku, movement: "In", qty: it.qty, reference: `${transaction.id} return` }).run();
        }
      } catch (e) {
        notify("Return processed locally, but saving to the server failed.", "error");
      }
    }
  }

  return (
    <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-[13px] min-w-[680px]">
          <thead>
            <tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
              <th className="px-4 py-3 font-medium">Receipt</th>
              <th className="px-4 py-3 font-medium">Cashier</th>
              <th className="px-4 py-3 font-medium">Date</th>
              <th className="px-4 py-3 font-medium">Payment</th>
              <th className="px-4 py-3 font-medium text-right">Items</th>
              <th className="px-4 py-3 font-medium text-right">Total (TZS 000)</th>
            </tr>
          </thead>
          <tbody>
            {loading && <SkeletonRows cols={6} />}
            {!loading && rows.map((t) => {
              const total = Math.round(t.items.reduce((s, it) => s + it.qty * it.price, 0) * (1 + TAX_RATE));
              const hasReturns = (t.returns || []).length > 0;
              return (
                <tr key={t.id} onClick={() => setSelected(t)} className="border-b border-slate-50 last:border-0 hover:bg-slate-50/70 cursor-pointer transition-colors">
                  <td className="px-4 py-3 font-mono font-medium text-[#111827]">
                    {t.id}
                    {hasReturns && <span className="ml-1.5 text-[10px] font-sans font-medium text-[#EF4444]">· returned</span>}
                  </td>
                  <td className="px-4 py-3 text-slate-700">{t.cashier}</td>
                  <td className="px-4 py-3 text-slate-500 font-mono">{t.date}</td>
                  <td className="px-4 py-3">
                    <span
                      className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
                      style={{ backgroundColor: `${POS_PAYMENT_COLOR[t.method]}14`, color: POS_PAYMENT_COLOR[t.method] }}
                    >
                      <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: POS_PAYMENT_COLOR[t.method] }} />
                      {t.method}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right font-mono text-slate-500">{t.items.reduce((s, it) => s + it.qty, 0)}</td>
                  <td className="px-4 py-3 text-right font-mono">{money(total)}</td>
                </tr>
              );
            })}
            {!loading && rows.length === 0 && (
              <tr>
                <td colSpan={6}>
                  <EmptyState icon={Receipt} title="No sales recorded yet" hint="Completed sales from the Checkout tab will appear here." />
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {selected && (
        <ReceiptPanel
          receipt={{ ...selected, subtotal: Math.round(selected.items.reduce((s, it) => s + it.qty * it.price, 0)), tax: Math.round(selected.items.reduce((s, it) => s + it.qty * it.price, 0) * TAX_RATE), total: Math.round(selected.items.reduce((s, it) => s + it.qty * it.price, 0) * (1 + TAX_RATE)) }}
          onClose={() => setSelected(null)}
          allowReturn
          onOpenReturn={() => setReturning(selected)}
          company={company}
        />
      )}
      {returning && (
        <ReturnFormPanel
          transaction={returning}
          onClose={() => setReturning(null)}
          onSubmit={(payload) => processReturn(returning, payload)}
        />
      )}
    </div>
  );
}

/* ----------------------------- BUSINESS ALERTS (SHARED UTILITY) ----------------------------- */

// Every alert here is computed from the same shared tables every module
// reads — nothing is a stored "notification" that can go stale. Clicking
// one navigates straight to the module where it can be acted on.
function useBusinessAlerts({ inventory, invoices, expenses, leaveRequests, workOrders, subscriptions }) {
  return useMemo(() => {
    const alerts = [];
    const todayStr = TODAY.toISOString().slice(0, 10);

    const outOfStock = inventory.rows.filter((it) => it.qty <= 0);
    if (outOfStock.length) {
      alerts.push({
        id: "out-of-stock", icon: Ban, color: "#EF4444", target: "inventory",
        title: `${outOfStock.length} item${outOfStock.length > 1 ? "s" : ""} out of stock`,
        subtitle: outOfStock.slice(0, 2).map((i) => i.name).join(", ") + (outOfStock.length > 2 ? "…" : ""),
      });
    }

    const lowStock = inventory.rows.filter((it) => it.qty > 0 && it.qty <= it.reorder);
    if (lowStock.length) {
      alerts.push({
        id: "low-stock", icon: AlertCircle, color: "#F59E0B", target: "inventory",
        title: `${lowStock.length} item${lowStock.length > 1 ? "s" : ""} low on stock`,
        subtitle: lowStock.slice(0, 2).map((i) => i.name).join(", ") + (lowStock.length > 2 ? "…" : ""),
      });
    }

    const overdue = invoices.rows.filter((inv) => inv.status !== "Paid" && inv.dueDate && inv.dueDate < todayStr);
    if (overdue.length) {
      const total = overdue.reduce((s, inv) => s + (lineTotal(inv.items).total - (inv.amountPaid || 0)), 0);
      alerts.push({
        id: "overdue-invoices", icon: Landmark, color: "#EF4444", target: "finance",
        title: `${overdue.length} invoice${overdue.length > 1 ? "s" : ""} overdue`,
        subtitle: `TZS ${money(Math.round(total))}k outstanding past due date`,
      });
    }

    const pendingExpenses = expenses.rows.filter((e) => e.status === "Pending");
    if (pendingExpenses.length) {
      alerts.push({
        id: "pending-expenses", icon: Wallet, color: "#F59E0B", target: "finance",
        title: `${pendingExpenses.length} expense${pendingExpenses.length > 1 ? "s" : ""} awaiting payment`,
        subtitle: pendingExpenses.slice(0, 2).map((e) => e.vendor).join(", ") + (pendingExpenses.length > 2 ? "…" : ""),
      });
    }

    const unusualExpenses = detectUnusualExpenses(expenses.rows);
    if (unusualExpenses.length) {
      alerts.push({
        id: "unusual-expenses", icon: AlertCircle, color: "#EF4444", target: "finance",
        title: `${unusualExpenses.length} unusual expense${unusualExpenses.length > 1 ? "s" : ""} detected`,
        subtitle: unusualExpenses.slice(0, 2).map((e) => `${e.vendor} (${e.multiple}× ${e.category} average)`).join(", "),
      });
    }

    const pendingLeave = leaveRequests.rows.filter((l) => l.status === "Pending");
    if (pendingLeave.length) {
      alerts.push({
        id: "pending-leave", icon: Clock, color: "#F59E0B", target: "hr",
        title: `${pendingLeave.length} leave request${pendingLeave.length > 1 ? "s" : ""} awaiting approval`,
        subtitle: pendingLeave.slice(0, 2).map((l) => l.employee).join(", ") + (pendingLeave.length > 2 ? "…" : ""),
      });
    }

    const overdueOrders = workOrders.rows.filter((w) => w.status !== "Completed" && w.status !== "Cancelled" && w.dueDate && w.dueDate < todayStr);
    if (overdueOrders.length) {
      alerts.push({
        id: "overdue-work-orders", icon: Factory, color: "#F59E0B", target: "manufacturing",
        title: `${overdueOrders.length} work order${overdueOrders.length > 1 ? "s" : ""} behind schedule`,
        subtitle: overdueOrders.slice(0, 2).map((w) => w.product).join(", ") + (overdueOrders.length > 2 ? "…" : ""),
      });
    }

    const dueSubscriptions = subscriptions.rows.filter((s) => s.status === "Active" && s.nextBillingDate < todayStr);
    if (dueSubscriptions.length) {
      alerts.push({
        id: "subscriptions-due", icon: Repeat, color: "#F59E0B", target: "sales",
        title: `${dueSubscriptions.length} subscription${dueSubscriptions.length > 1 ? "s" : ""} due for billing`,
        subtitle: dueSubscriptions.slice(0, 2).map((s) => s.customer).join(", ") + (dueSubscriptions.length > 2 ? "…" : ""),
      });
    }

    return alerts;
  }, [inventory.rows, invoices.rows, expenses.rows, leaveRequests.rows, workOrders.rows, subscriptions.rows]);
}

function NotificationCenter({ inventory, invoices, expenses, leaveRequests, workOrders, subscriptions, onNavigate }) {
  const [open, setOpen] = useState(false);
  const alerts = useBusinessAlerts({ inventory, invoices, expenses, leaveRequests, workOrders, subscriptions });

  return (
    <div className="relative">
      <button
        onClick={() => setOpen((o) => !o)}
        className="relative text-slate-400 hover:text-slate-600"
        aria-label={"Notifications" + (alerts.length ? " (" + alerts.length + " alerts)" : "")}
      >
        <Bell size={17} strokeWidth={1.75} />
        {alerts.length > 0 && (
          <span className="absolute -top-1.5 -right-1.5 min-w-[16px] h-4 px-0.5 bg-[#EF4444] rounded-full ring-1 ring-white flex items-center justify-center text-[9px] font-bold text-white leading-none">{alerts.length > 9 ? "9+" : alerts.length}</span>
        )}
      </button>

      {open && (
        <>
          <div className="fixed inset-0 z-30" onClick={() => setOpen(false)} />
          <div
            className="absolute right-0 top-full mt-2 w-[320px] bg-white rounded-xl border border-slate-200/80 shadow-lg z-40 overflow-hidden"
            style={{ animation: "toastIn .15s ease-out" }}
          >
            <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between">
              <h3 className="text-[13px] font-semibold text-[#111827]">Notifications</h3>
              {alerts.length > 0 && <span className="text-[11px] text-slate-400 font-mono">{alerts.length}</span>}
            </div>
            <div className="max-h-[360px] overflow-y-auto">
              {alerts.length === 0 ? (
                <div className="px-4 py-8 text-center">
                  <CheckCircle2 size={20} className="text-[#16A34A] mx-auto mb-2" />
                  <p className="text-[12.5px] text-slate-500">All clear — nothing needs attention right now.</p>
                </div>
              ) : (
                alerts.map((a) => {
                  const Icon = a.icon;
                  return (
                    <button
                      key={a.id}
                      onClick={() => { onNavigate(a.target); setOpen(false); }}
                      className="w-full flex items-start gap-3 px-4 py-3 text-left hover:bg-slate-50/70 transition-colors border-b border-slate-50 last:border-0"
                    >
                      <div className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0" style={{ backgroundColor: `${a.color}14` }}>
                        <Icon size={15} style={{ color: a.color }} />
                      </div>
                      <div className="min-w-0">
                        <p className="text-[12.5px] font-medium text-[#111827]">{a.title}</p>
                        <p className="text-[11.5px] text-slate-400 truncate">{a.subtitle}</p>
                      </div>
                    </button>
                  );
                })
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

// A real command palette — the Cmd+K pattern every serious productivity
// tool uses (Linear, Notion, Superhuman, VS Code), deliberately chosen
// because it's not a pattern SME-focused competitors typically bother
// with at all. Genuinely useful for the exact person this system claims
// to serve at the "large business" end: someone doing the same handful
// of actions dozens of times a day, for whom reaching for a mouse and
// hunting through a sidebar is real, measurable friction. Only ever
// shows modules already in `modules` — the same RBAC- and entitlement-
// filtered list the sidebar itself uses, so this can never let someone
// jump to something they don't actually have access to.
const PALETTE_ACTIONS = [
  { id: "new-invoice", label: "Create Invoice", module: "sales", intent: { tab: "invoices", openForm: true } },
  { id: "new-lead", label: "New Lead", module: "crm", intent: { tab: "leads" } },
  { id: "approve-leave", label: "Approve Leave", module: "hr", intent: { tab: "leave" } },
  { id: "record-payment", label: "Record Payment", module: "finance", intent: { tab: "receivables" } },
  { id: "record-expense", label: "Record Expense", module: "finance", intent: { tab: "expenses" } },
  { id: "settings", label: "Open Settings", module: "settings", intent: null },
];

function CommandPalette({ modules, crm, invoices, inventory, expenses, onNavigate, onNavigateWithIntent, onClose }) {
  const [query, setQuery] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef(null);

  useEffect(() => { inputRef.current?.focus(); }, []);

  const moduleResults = modules
    .filter((m) => m.label.toLowerCase().includes(query.toLowerCase()))
    .map((m) => ({ id: `mod-${m.id}`, label: m.label, icon: m.icon, kind: "Go to", action: () => onNavigate(m.id) }));

  const actionResults = PALETTE_ACTIONS
    .filter((a) => modules.some((m) => m.id === a.module)) // only real actions for modules this user can actually reach
    .filter((a) => a.label.toLowerCase().includes(query.toLowerCase()))
    .map((a) => ({ id: a.id, label: a.label, icon: Zap, kind: "Quick action", action: () => (a.intent ? onNavigateWithIntent(a.module, a.intent) : onNavigate(a.module)) }));

  // Real global data search — actual customers, invoices, and products,
  // searchable from anywhere. RBAC is preserved by construction, not by a
  // separate check that could drift: each category only searches at all
  // if its parent module is already in the RBAC- and entitlement-filtered
  // `modules` list this palette receives — the identical source of truth
  // the sidebar renders from — so a role without CRM access never sees a
  // customer name surface here. Requires 2+ characters (a single letter
  // matches half of everything) and caps each category at 4 results so
  // the list stays scannable. Selecting a record lands on the right
  // module and tab — the real capability the intent system has — not a
  // deep-link to the exact record's detail panel, which the intent system
  // doesn't support and this doesn't pretend to.
  const q = query.trim().toLowerCase();
  const canSee = (moduleId) => modules.some((m) => m.id === moduleId);
  // Month understanding for queries like "Expenses July" — a real month
  // token (3+ letters, English) becomes a real YYYY-MM filter against the
  // current year; generic intent words ("expenses", "gharama") are
  // stripped rather than matched literally against vendor names.
  const MONTH_NAMES = ["january","february","march","april","may","june","july","august","september","october","november","december"];
  let monthKey = null; const textTerms = [];
  for (const t of q.split(/\s+/).filter(Boolean)) {
    const mi = t.length >= 3 ? MONTH_NAMES.findIndex((m) => m.startsWith(t)) : -1;
    if (mi >= 0 && monthKey === null) monthKey = `${TODAY.getFullYear()}-${String(mi + 1).padStart(2, "0")}`;
    else if (!["expense", "expenses", "gharama"].includes(t)) textTerms.push(t);
  }
  const expText = textTerms.join(" ");
  const recordResults = q.length < 2 ? [] : [
    ...(canSee("crm") ? (crm?.rows || [])
      .filter((l) => l.company.toLowerCase().includes(q) || (l.name || "").toLowerCase().includes(q))
      .slice(0, 4)
      .map((l) => ({ id: `rec-lead-${l.id}`, label: l.company, sub: l.name, icon: Building2, kind: "Customer / Lead", action: () => onNavigateWithIntent("crm", { tab: "leads" }) })) : []),
    ...(canSee("sales") ? (invoices?.rows || [])
      .filter((inv) => inv.id.toLowerCase().includes(q) || inv.customer.toLowerCase().includes(q))
      .slice(0, 4)
      .map((inv) => ({ id: `rec-inv-${inv.id}`, label: inv.id, sub: `${inv.customer} · ${inv.status}`, icon: ReceiptText, kind: "Invoice", action: () => onNavigateWithIntent("sales", { tab: "invoices" }) })) : []),
    ...(canSee("inventory") ? (inventory?.rows || [])
      .filter((it) => it.name.toLowerCase().includes(q) || it.sku.toLowerCase().includes(q))
      .slice(0, 4)
      .map((it) => ({ id: `rec-item-${it.sku}`, label: it.name, sub: `${it.sku} · ${it.qty} in stock`, icon: Package, kind: "Product", action: () => onNavigateWithIntent("inventory", { tab: "stock" }) })) : []),
    ...(canSee("finance") ? (expenses?.rows || [])
      .filter((e) => {
        const matchText = !expText || e.vendor.toLowerCase().includes(expText) || (e.category || "").toLowerCase().includes(expText);
        const matchMonth = !monthKey || (e.date || "").startsWith(monthKey);
        return (expText || monthKey) && matchText && matchMonth;
      })
      .slice(0, 4)
      .map((e) => ({ id: `rec-exp-${e.id}`, label: e.vendor, sub: `${e.category} · ${e.date} · TZS ${money(Math.round(e.amount))}k`, icon: ClipboardList, kind: "Expense", action: () => onNavigateWithIntent("finance", { tab: "expenses" }) })) : []),
  ];

  const results = [...recordResults, ...actionResults, ...moduleResults];

  function handleKeyDown(e) {
    if (e.key === "ArrowDown") { e.preventDefault(); setSelectedIndex((i) => Math.min(i + 1, results.length - 1)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setSelectedIndex((i) => Math.max(i - 1, 0)); }
    else if (e.key === "Enter" && results[selectedIndex]) { results[selectedIndex].action(); onClose(); }
  }

  return (
    <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[12vh]">
      <div className="absolute inset-0 bg-[#111827]/30 backdrop-blur-[2px]" onClick={onClose} />
      <div className="relative w-full max-w-lg mx-4 bg-white rounded-2xl shadow-2xl overflow-hidden" style={{ animation: "fadeInUp .15s ease-out" }}>
        <div className="flex items-center gap-2.5 px-4 py-3 border-b border-slate-100">
          <Search size={16} className="text-slate-400 shrink-0" />
          <input
            ref={inputRef} value={query} onChange={(e) => { setQuery(e.target.value); setSelectedIndex(0); }} onKeyDown={handleKeyDown}
            placeholder="Search customers, invoices, products — or jump anywhere..."
            className="flex-1 outline-none text-[14px] placeholder:text-slate-400"
          />
          <kbd className="text-[10px] font-mono text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded">Esc</kbd>
        </div>
        <div className="max-h-80 overflow-y-auto py-1.5">
          {results.length === 0 && <p className="text-[12.5px] text-slate-400 text-center py-8">No matches.</p>}
          {results.map((r, i) => {
            const Icon = r.icon;
            return (
              <button
                key={r.id} onClick={() => { r.action(); onClose(); }} onMouseEnter={() => setSelectedIndex(i)}
                className={`w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors ${i === selectedIndex ? "bg-[#16A34A]/5" : ""}`}
              >
                <div className="w-7 h-7 rounded-lg flex items-center justify-center shrink-0" style={{ backgroundColor: i === selectedIndex ? "#DCFCE7" : "#F3F4F6" }}>
                  <Icon size={14} style={{ color: i === selectedIndex ? "#16A34A" : "#94A3B8" }} />
                </div>
                <span className={`text-[13px] flex-1 min-w-0 ${i === selectedIndex ? "font-medium text-[#111827]" : "text-slate-600"}`}>
                  <span className="block truncate">{r.label}</span>
                  {r.sub && <span className="block text-[10.5px] text-slate-400 truncate font-normal">{r.sub}</span>}
                </span>
                <span className="text-[10.5px] text-slate-400 shrink-0">{r.kind}</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function ProfileMenu({ currentUser, session, onSignOut }) {
  const [open, setOpen] = useState(false);
  const initials = currentUser.name.split(" ").map((p) => p[0]).slice(0, 2).join("").toUpperCase() || "?";

  return (
    <div className="relative">
      <button
        onClick={() => setOpen((o) => !o)}
        className="w-8 h-8 rounded-full flex items-center justify-center text-white text-[12px] font-medium"
        style={{ background: "linear-gradient(135deg, #22C55E, #15803D)", boxShadow: "0 3px 10px rgba(34,197,94,.4)" }}
        aria-label="Account menu"
      >
        {initials}
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-30" onClick={() => setOpen(false)} />
          <div className="absolute right-0 top-full mt-2 w-56 bg-white rounded-xl border border-slate-200/80 shadow-lg z-40 overflow-hidden">
            <div className="px-4 py-3 border-b border-slate-100">
              <p className="text-[13px] font-medium text-[#111827] truncate">{currentUser.name}</p>
              <p className="text-[11.5px] text-slate-400">{currentUser.role}</p>
              {session && !session.demo && <p className="text-[10.5px] text-slate-400 truncate mt-0.5">{session.email}</p>}
            </div>
            {(!session || session.demo) && (
              <p className="px-4 py-2.5 text-[11px] text-slate-400 border-b border-slate-100">Demo session — not a real signed-in account.</p>
            )}
            <button onClick={onSignOut} className="w-full flex items-center gap-2 text-[12.5px] text-[#EF4444] hover:bg-[#FEE2E2] px-4 py-2.5 text-left transition-colors">
              <LogOut size={13} /> {session && !session.demo ? "Sign out" : "Exit demo"}
            </button>
          </div>
        </>
      )}
    </div>
  );
}

/* ---------------------------------- CUSTOMER PORTAL ---------------------------------- */

// The real security boundary here is the schema, not this component. In
// live mode, the RLS policies added alongside profiles.customer_ref
// (invoices_customer_read, orders_customer_read, etc.) mean a signed-in
// External Client's session can only ever receive their own rows from the
// database — sb() runs the identical query an internal user's session
// would, and Postgres decides what comes back based on who's asking. This
// component's own "match by customer name" filtering below is a second,
// redundant safety net for demo mode (where there is no real RLS to rely
// on) — in live mode it's filtering a result set that was already scoped
// correctly before it ever reached the browser.
function CustomerPortal({ currentUser, invoices, filesHook, onSignOut }) {
  const [tab, setTab] = useState("invoices");
  const orders = useCompanyTable("sales_orders", ordersSeed, { mapRow: mapOrderRow });
  const tickets = useCompanyTable("support_tickets", supportTicketsSeed, { mapRow: mapTicketRow });
  const connections = useCompanyTable("integration_connections", INTEGRATION_CONNECTIONS.map((c) => ({ id: c.id, enabled: false, tenantId: "", clientId: "", paymentLink: "", paypalMeLink: "", webhookUrl: "", apiKey: "", businessNumber: "", storeUrl: "", terminalId: "" })), { mapRow: mapIntegrationConnectionRow });

  // Demo mode has no real customer_ref to filter by — this picks the
  // first customer name appearing in the seed data purely so the portal
  // has something real to show, and says so plainly rather than quietly
  // showing every customer's invoices as if that were normal.
  const effectiveCustomer = currentUser.customerRef || invoices.rows[0]?.customer || "Demo Customer";
  const myInvoices = invoices.rows.filter((inv) => inv.customer === effectiveCustomer);
  const myOrders = orders.rows.filter((o) => o.customer === effectiveCustomer);
  const myTickets = tickets.rows.filter((t) => t.customer === effectiveCustomer);
  const myDocuments = filesHook.rows.filter((f) => myInvoices.some((i) => i.id === f.linkedRecord) || myOrders.some((o) => o.id === f.linkedRecord));

  const stripe = connections.rows.find((c) => c.id === "stripe");
  const paypal = connections.rows.find((c) => c.id === "paypal");

  const PORTAL_TABS = [
    { id: "invoices", label: "Invoices", icon: ReceiptText },
    { id: "orders", label: "Orders", icon: Package },
    { id: "documents", label: "Documents", icon: FileText },
    { id: "support", label: "Support", icon: Headphones },
    { id: "chat", label: "Chat with AI", icon: Brain },
  ];

  return (
    <div className="min-h-screen bg-[#F8FAFC]" style={{ fontFamily: "'Inter', system-ui, sans-serif" }}>
      <header className="bg-white border-b border-slate-200/80 px-4 sm:px-6 py-3.5 flex items-center justify-between sticky top-0 z-20">
        <div className="flex items-center gap-2.5">
          <BrandMark size={32} textSize={14} />
          <div>
            <p className="text-[13.5px] font-semibold text-[#111827] leading-tight">Customer Portal</p>
            <p className="text-[10.5px] text-slate-400 leading-tight">{effectiveCustomer}</p>
          </div>
        </div>
        <ProfileMenu currentUser={currentUser} session={{ demo: !currentUser.customerRef }} onSignOut={onSignOut} />
      </header>

      {!currentUser.customerRef && (
        <div className="bg-[#F59E0B]/10 border-b border-[#F59E0B]/20 px-4 sm:px-6 py-2">
          <p className="text-[11.5px] text-[#8a670a]">Demo mode — showing sample data for "{effectiveCustomer}" since there's no real signed-in customer identity yet. In live mode, this portal shows exactly one customer's own records, enforced by the database itself, not by this screen.</p>
        </div>
      )}

      <div className="max-w-3xl mx-auto px-4 sm:px-6 py-5">
        <div className="flex items-center gap-1 bg-white border border-slate-200/80 rounded-lg p-1 mb-5 overflow-x-auto w-fit max-w-full">
          {PORTAL_TABS.map((t) => {
            const Icon = t.icon;
            const isActive = tab === t.id;
            return (
              <button key={t.id} onClick={() => setTab(t.id)} className={`text-[12px] font-medium px-3 py-1.5 rounded-md flex items-center gap-1.5 whitespace-nowrap transition-colors ${isActive ? "bg-[#16A34A] text-white" : "text-slate-500 hover:text-slate-700"}`}>
                <Icon size={13} /> {t.label}
              </button>
            );
          })}
        </div>

        <PortalFeedbackWidget currentUser={currentUser} />
        {tab === "invoices" && <CustomerInvoicesTab myInvoices={myInvoices} stripe={stripe} paypal={paypal} />}
        {tab === "orders" && <CustomerOrdersTab myOrders={myOrders} />}
        {tab === "documents" && <CustomerDocumentsTab myDocuments={myDocuments} />}
        {tab === "support" && <CustomerSupportTab myTickets={myTickets} tickets={tickets} customerName={effectiveCustomer} />}
        {tab === "chat" && <CustomerAIChat customerName={effectiveCustomer} myInvoices={myInvoices} myOrders={myOrders} />}
      </div>
    </div>
  );
}

// Voice of the customer, collected where the customer actually is: the
// portal. One-tap 0–10 NPS with an optional comment, written to the real
// customer_feedback table. Dismisses after submitting; a portal that
// nags for ratings on every visit trains people to ignore it.
function PortalFeedbackWidget({ currentUser }) {
  const [score, setScore] = useState(null);
  const [comment, setComment] = useState("");
  const [done, setDone] = useState(false);
  if (done) return null;
  async function submit() {
    if (score === null) return;
    setDone(true);
    notify("Thank you — your feedback landed with the team.");
    if (IS_CONFIGURED) {
      try { await sb("customer_feedback").insert({ customer_name: currentUser.customerRef || currentUser.name, nps_score: score, comment: comment.trim() || null }).run(); } catch (_e) {}
    }
  }
  return (
    <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 mb-4">
      <p className="text-[12.5px] font-medium text-[#111827]">How likely are you to recommend us? <span className="text-slate-400 font-normal">(0 = not at all, 10 = extremely)</span></p>
      <div className="flex flex-wrap gap-1.5 mt-2">
        {Array.from({ length: 11 }, (_, i) => (
          <button key={i} onClick={() => setScore(i)} className={`w-8 h-8 rounded-lg text-[12px] font-mono font-medium border ${score === i ? "bg-[#16A34A] text-white border-[#16A34A]" : "border-slate-200 text-slate-500 hover:border-slate-300"}`}>{i}</button>
        ))}
      </div>
      {score !== null && (
        <div className="flex gap-2 mt-2.5">
          <input className={inputClass} value={comment} onChange={(e) => setComment(e.target.value)} placeholder="Anything we should know? (optional)" />
          <button onClick={submit} className="btn-primary text-white text-[12px] font-medium rounded-lg px-3.5 shrink-0">Send</button>
        </div>
      )}
    </div>
  );
}

function CustomerInvoicesTab({ myInvoices, stripe, paypal }) {
  const [payingId, setPayingId] = useState(null);

  // Self-serve receipt — the same proven printAsPDF isolation every
  // internal report uses (browser print-to-PDF, clean window, no app
  // chrome), now in the customer's own hands: real invoice data, real
  // payment history, no email round-trip to the business.
  function downloadReceipt(inv) {
    const t = lineTotal(inv.items);
    const items = inv.items.map((it) => `<tr><td>${it.name}</td><td class="right">${it.qty}</td><td class="right">${money(it.rate)}k</td><td class="right">${money(Math.round(it.qty * it.rate))}k</td></tr>`).join("");
    const pays = (inv.payments || []).map((p) => `<tr><td>${p.date}</td><td>${p.method || "—"}</td><td class="right">${money(Math.round(p.amount))}k</td></tr>`).join("");
    printAsPDF(`Receipt ${inv.id}`, `
      <h1>Receipt — ${inv.id}</h1>
      <p style="color:#888;font-size:12px;">${inv.customer} · issued ${inv.date} · status: ${inv.status}</p>
      <table><thead><tr><th>Item</th><th class="right">Qty</th><th class="right">Rate</th><th class="right">Amount</th></tr></thead><tbody>${items}</tbody></table>
      <p style="text-align:right;font-weight:bold;margin-top:10px;">Total: TZS ${money(Math.round(t.total))}k · Paid: TZS ${money(Math.round(inv.amountPaid || 0))}k</p>
      ${pays ? "<h2 style=\"font-size:13px;margin-top:16px;\">Payments</h2><table><thead><tr><th>Date</th><th>Method</th><th class=\"right\">Amount</th></tr></thead><tbody>" + pays + "</tbody></table>" : ""}
      <p style="font-size:10.5px;color:#888;margin-top:18px;">Generated from live records by the customer portal.</p>
    `);
  }
  const canPayOnline = stripe?.enabled && stripe?.paymentLink || paypal?.enabled && paypal?.paypalMeLink;

  function payOnline(invoiceId) {
    const url = stripe?.enabled && stripe?.paymentLink ? stripe.paymentLink : paypal.paypalMeLink;
    // Neither Stripe Payment Links nor a plain PayPal.me link support a
    // dynamic amount from a URL param without more setup on the business's
    // side — the honest move is opening the real page and telling the
    // customer to reference their invoice number, not silently pretending
    // the amount carried over.
    notify(`Opening the payment page — reference invoice ${invoiceId} so ${stripe?.enabled ? "the business" : "PayPal"} can match your payment.`);
    window.open(url, "_blank");
    setPayingId(invoiceId);
  }

  return (
    <div className="space-y-3">
      {!canPayOnline && (
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-3.5">
          <p className="text-[11.5px] text-slate-400">Online payment isn&apos;t configured yet — the business needs to connect Stripe or PayPal in their own Integrations settings first.</p>
        </div>
      )}
      {myInvoices.length === 0 && <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm"><EmptyState icon={ReceiptText} title="No invoices yet" hint="Invoices billed to you will appear here." /></div>}
      {myInvoices.map((inv) => {
        const { total } = lineTotal(inv.items);
        const balance = total - (inv.amountPaid || 0);
        return (
          <div key={inv.id} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5">
            <div className="flex items-start justify-between mb-2">
              <div><p className="text-[13.5px] font-semibold text-[#111827]">{inv.id}</p><p className="text-[11px] text-slate-400">Due {inv.dueDate}</p></div>
              <span className={`text-[10.5px] font-medium px-2 py-0.5 rounded-full ${inv.status === "Paid" ? "bg-[#16A34A]/10 text-[#16A34A]" : "bg-[#EF4444]/10 text-[#EF4444]"}`}>{inv.status}</span>
              <button onClick={() => downloadReceipt(inv)} className="text-[11px] font-medium text-[#16A34A] hover:underline flex items-center gap-1 ml-2"><Download size={11} /> Receipt</button>
            </div>
            <div className="flex items-center justify-between mb-3">
              <p className="text-[20px] font-mono font-bold text-[#111827]">TZS {money(Math.round(total))}k</p>
              {balance > 0 && <p className="text-[11.5px] text-[#EF4444]">TZS {money(Math.round(balance))}k due</p>}
            </div>
            {balance > 0 && canPayOnline && (
              <button onClick={() => payOnline(inv.id)} className="btn-primary text-white text-[12.5px] font-medium rounded-lg py-2.5 w-full flex items-center justify-center gap-2">
                <CreditCard size={14} /> Pay Online
              </button>
            )}
            {payingId === inv.id && <p className="text-[11px] text-slate-400 mt-2 text-center">Paid already? It can take a moment to reflect here — check back shortly.</p>}
          </div>
        );
      })}
    </div>
  );
}

function CustomerOrdersTab({ myOrders }) {
  const ORDER_STEPS = ["Pending", "Confirmed", "Fulfilled"];
  return (
    <div className="space-y-3">
      {myOrders.length === 0 && <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm"><EmptyState icon={Package} title="No orders yet" hint="Your orders will appear here once placed." /></div>}
      {myOrders.map((o) => {
        const stepIndex = o.status === "Cancelled" ? -1 : ORDER_STEPS.indexOf(o.status);
        return (
          <div key={o.id} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5">
            <div className="flex items-center justify-between mb-3">
              <p className="text-[13.5px] font-semibold text-[#111827]">{o.id}</p>
              <span className="text-[11px] text-slate-400">{o.date}</span>
            </div>
            {o.status === "Cancelled" ? (
              <p className="text-[12.5px] text-[#EF4444]">This order was cancelled.</p>
            ) : (
              <div className="flex items-center">
                {ORDER_STEPS.map((step, i) => (
                  <React.Fragment key={step}>
                    <div className="flex flex-col items-center">
                      <div className={`w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold ${i <= stepIndex ? "bg-[#16A34A] text-white" : "bg-slate-100 text-slate-400"}`}>{i <= stepIndex ? <CheckCircle2 size={13} /> : i + 1}</div>
                      <span className={`text-[10px] mt-1 ${i <= stepIndex ? "text-[#111827] font-medium" : "text-slate-400"}`}>{step}</span>
                    </div>
                    {i < ORDER_STEPS.length - 1 && <div className={`flex-1 h-0.5 mx-1 ${i < stepIndex ? "bg-[#16A34A]" : "bg-slate-100"}`} />}
                  </React.Fragment>
                ))}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function CustomerDocumentsTab({ myDocuments }) {
  return (
    <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm">
      {myDocuments.length === 0 ? (
        <EmptyState icon={FileText} title="No documents yet" hint="Contracts and paperwork tied to your invoices or orders will appear here." />
      ) : (
        <div className="divide-y divide-slate-50">
          {myDocuments.map((f) => {
            const meta = FILE_TYPE_STYLE[f.type] || FILE_TYPE_STYLE.pdf;
            const Icon = meta.Icon;
            return (
              <div key={f.id} className="flex items-center gap-2.5 px-4 py-3">
                <div className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0" style={{ backgroundColor: `${meta.color}14` }}><Icon size={14} style={{ color: meta.color }} /></div>
                <div className="min-w-0 flex-1"><p className="text-[12.5px] font-medium text-[#111827] truncate">{f.name}</p><p className="text-[11px] text-slate-400">{f.size} · {f.date}</p></div>
                <span className="text-[11px] text-slate-300">No file storage in this demo</span>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function CustomerSupportTab({ myTickets, tickets, customerName }) {
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ subject: "", category: "General", description: "" });

  async function submitTicket(e) {
    e.preventDefault();
    if (!form.subject.trim()) return;
    const draft = { id: docId("TK"), subject: form.subject, customer: customerName, category: form.category, priority: "Medium", status: "Open", assignee: null, createdDate: TODAY.toISOString().slice(0, 10) };
    tickets.setRows((prev) => [draft, ...prev]);
    setShowForm(false);
    setForm({ subject: "", category: "General", description: "" });
    notify(`Ticket ${draft.id} submitted — the support team will follow up.`);
    if (IS_CONFIGURED) {
      try { await sb("support_tickets").insert({ doc_number: draft.id, subject: draft.subject, customer: draft.customer, category: draft.category }).run(); } catch (_e) { notify("Ticket saved locally, but sending to the server failed.", "error"); }
    }
  }

  return (
    <div className="space-y-3">
      <button onClick={() => setShowForm((s) => !s)} className="btn-primary text-white text-[12.5px] font-medium rounded-lg py-2.5 px-4 flex items-center gap-2 w-full sm:w-auto">
        <Plus size={14} /> Open a Support Ticket
      </button>
      {showForm && (
        <form onSubmit={submitTicket} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5 space-y-3">
          <FormField label="Subject" required><input className={inputClass} value={form.subject} onChange={(e) => setForm((f) => ({ ...f, subject: e.target.value }))} placeholder="What's this about?" /></FormField>
          <FormField label="Category">
            <select className={inputClass} value={form.category} onChange={(e) => setForm((f) => ({ ...f, category: e.target.value }))}>
              {["Billing", "Technical", "Product", "General"].map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </FormField>
          <FormField label="Details"><textarea className={inputClass} rows={4} value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} placeholder="Tell us more..." /></FormField>
          <button type="submit" className="btn-primary text-white text-[12.5px] font-medium rounded-lg py-2.5 w-full">Submit Ticket</button>
        </form>
      )}
      <div className="space-y-2">
        {myTickets.length === 0 && <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm"><EmptyState icon={Headphones} title="No tickets yet" hint="Tickets you open will show up here." /></div>}
        {myTickets.map((t) => (
          <div key={t.id} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 flex items-center justify-between">
            <div className="min-w-0"><p className="text-[12.5px] font-medium text-[#111827] truncate">{t.subject}</p><p className="text-[11px] text-slate-400">{t.id} · {t.category} · {t.createdDate}</p></div>
            <span className={`text-[10.5px] font-medium px-2 py-0.5 rounded-full shrink-0 ml-2 ${t.status === "Resolved" || t.status === "Closed" ? "bg-[#16A34A]/10 text-[#16A34A]" : "bg-[#F59E0B]/10 text-[#F59E0B]"}`}>{t.status}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// A deliberately narrow AI persona — it only ever sees THIS customer's own
// invoices and orders, never the full business snapshot every internal
// persona in section 23 reads from. A customer-facing AI leaking another
// customer's balance, or the business's internal costs and margins, would
// be a real privacy failure, not a hypothetical one; the safest fix is
// structural — this component is never given access to anything broader
// than what's already been filtered to this one customer above.
function CustomerAIChat({ customerName, myInvoices, myOrders }) {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);

  async function send() {
    if (!input.trim() || busy) return;
    const userMsg = { role: "user", content: input.trim() };
    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    setBusy(true);
    try {
      const snapshot = {
        customer: customerName,
        invoices: myInvoices.map((i) => ({ id: i.id, status: i.status, due_date: i.dueDate, total_tzs_k: Math.round(lineTotal(i.items).total), balance_tzs_k: Math.round(lineTotal(i.items).total - (i.amountPaid || 0)) })),
        orders: myOrders.map((o) => ({ id: o.id, status: o.status, order_date: o.date })),
      };
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 500,
          system: `You are a customer support assistant for ${customerName}. You can only discuss ${customerName}'s own invoices and orders, provided below as JSON — never invent information not present here, and never discuss any other customer or internal business figures, because you have no access to them. If asked about something outside this data, say you don't have that information and suggest opening a support ticket.\n\nYour data:\n${JSON.stringify(snapshot, null, 2)}`,
          messages: [...messages, userMsg],
        }),
      });
      const data = await response.json();
      const text = data.content?.find((c) => c.type === "text")?.text || "Sorry, I couldn't process that.";
      setMessages((prev) => [...prev, { role: "assistant", content: text }]);
    } catch (_e) {
      setMessages((prev) => [...prev, { role: "assistant", content: "I couldn't reach the AI service — please try again in a moment." }]);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm flex flex-col h-[480px]">
      <div className="px-4 py-3 border-b border-slate-100">
        <p className="text-[12.5px] font-medium text-[#111827]">Chat with AI</p>
        <p className="text-[11px] text-slate-400">Scoped to your own invoices and orders only — nothing else about this business.</p>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {messages.length === 0 && <p className="text-[12.5px] text-slate-400 text-center py-8">Ask about your invoices or order status.</p>}
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === "user" ? "justify-end" : "justify-start"}`}>
            <div className={`max-w-[80%] rounded-xl px-3.5 py-2.5 text-[13px] ${m.role === "user" ? "btn-primary text-white" : "bg-slate-50 text-slate-700"}`}>{m.content}</div>
          </div>
        ))}
        {busy && <div className="flex justify-start"><LoaderCircle size={16} className="animate-spin text-[#16A34A]" /></div>}
      </div>
      <div className="p-3 border-t border-slate-100 flex gap-2">
        <input value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} placeholder="Ask about your invoices or orders..." className="flex-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-[13px] outline-none focus:border-[#16A34A]" />
        <button onClick={send} disabled={busy || !input.trim()} className="btn-primary text-white rounded-lg px-3 disabled:opacity-40" aria-label="Send"><Send size={15} /></button>
      </div>
    </div>
  );
}

/* ---------------------------------- SUPPLIER PORTAL ---------------------------------- */

// The same real security design as the Customer Portal (section 40): RLS
// policies added alongside profiles.customer_ref are what actually scope
// a supplier's session to their own purchase orders, contracts, and
// payment history — this component's own filtering is a demo-mode
// fallback, not the security boundary, in live mode it's just narrowing
// a result set the database had already scoped correctly.
function ExternalSupplierPortal({ currentUser, onSignOut }) {
  const [tab, setTab] = useState("orders");
  const purchaseOrders = useCompanyTable("procurement_purchase_orders", purchaseOrdersSeed, {
    select: "*,purchase_order_items(*)", mapRow: mapPurchaseOrderRow,
  });
  const contracts = useCompanyTable("procurement_contracts", procurementContractsSeed, { mapRow: mapProcurementContractRow });
  const expenses = useCompanyTable("finance_expenses", expensesSeed, { mapRow: mapExpenseRow });
  const files = useCompanyTable("documents", filesSeed, { mapRow: mapFileRow });

  const effectiveSupplier = currentUser.customerRef || purchaseOrders.rows[0]?.supplier || "Demo Supplier";
  const myOrders = purchaseOrders.rows.filter((po) => po.supplier === effectiveSupplier);
  const myContracts = contracts.rows.filter((c) => c.supplier === effectiveSupplier);
  const myPayments = expenses.rows.filter((e) => e.vendor === effectiveSupplier);
  const myDocuments = files.rows.filter((f) => myOrders.some((po) => po.id === f.linkedRecord));

  const PORTAL_TABS = [
    { id: "orders", label: "Purchase Orders", icon: ClipboardList },
    { id: "invoices", label: "Upload Invoices", icon: UploadCloud },
    { id: "payments", label: "Track Payments", icon: Wallet },
    { id: "contracts", label: "Contracts", icon: FileCheck },
    { id: "deliveries", label: "Deliveries", icon: Truck },
  ];

  return (
    <div className="min-h-screen bg-[#F8FAFC]" style={{ fontFamily: "'Inter', system-ui, sans-serif" }}>
      <header className="bg-white border-b border-slate-200/80 px-4 sm:px-6 py-3.5 flex items-center justify-between sticky top-0 z-20">
        <div className="flex items-center gap-2.5">
          <BrandMark size={32} textSize={14} />
          <div>
            <p className="text-[13.5px] font-semibold text-[#111827] leading-tight">Supplier Portal</p>
            <p className="text-[10.5px] text-slate-400 leading-tight">{effectiveSupplier}</p>
          </div>
        </div>
        <ProfileMenu currentUser={currentUser} session={{ demo: !currentUser.customerRef }} onSignOut={onSignOut} />
      </header>

      {!currentUser.customerRef && (
        <div className="bg-[#F59E0B]/10 border-b border-[#F59E0B]/20 px-4 sm:px-6 py-2">
          <p className="text-[11.5px] text-[#8a670a]">Demo mode — showing sample data for "{effectiveSupplier}" since there's no real signed-in supplier identity yet. In live mode, this portal shows exactly one supplier's own records, enforced by the database itself.</p>
        </div>
      )}

      <div className="max-w-3xl mx-auto px-4 sm:px-6 py-5">
        <div className="flex items-center gap-1 bg-white border border-slate-200/80 rounded-lg p-1 mb-5 overflow-x-auto w-fit max-w-full">
          {PORTAL_TABS.map((t) => {
            const Icon = t.icon;
            const isActive = tab === t.id;
            return (
              <button key={t.id} onClick={() => setTab(t.id)} className={`text-[12px] font-medium px-3 py-1.5 rounded-md flex items-center gap-1.5 whitespace-nowrap transition-colors ${isActive ? "bg-[#16A34A] text-white" : "text-slate-500 hover:text-slate-700"}`}>
                <Icon size={13} /> {t.label}
              </button>
            );
          })}
        </div>

        {tab === "orders" && <SupplierOrdersTab myOrders={myOrders} />}
        {tab === "invoices" && <SupplierInvoiceUploadTab myOrders={myOrders} filesHook={files} />}
        {tab === "payments" && <SupplierPaymentsTab myPayments={myPayments} />}
        {tab === "contracts" && <SupplierContractsTab myContracts={myContracts} />}
        {tab === "deliveries" && <SupplierDeliveriesTab myOrders={myOrders} purchaseOrdersHook={purchaseOrders} />}
      </div>
    </div>
  );
}

function SupplierOrdersTab({ myOrders }) {
  return (
    <div className="space-y-3">
      {myOrders.length === 0 && <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm"><EmptyState icon={ClipboardList} title="No purchase orders yet" hint="Purchase orders issued to you will appear here as soon as they're raised." /></div>}
      {myOrders.map((po) => {
        const total = po.items.reduce((s, it) => s + it.qty * it.cost, 0);
        return (
          <div key={po.id} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5">
            <div className="flex items-start justify-between mb-3">
              <div><p className="text-[13.5px] font-semibold text-[#111827]">{po.id}</p><p className="text-[11px] text-slate-400">Ordered {po.orderDate}{po.expectedDate ? ` · expected ${po.expectedDate}` : ""}</p></div>
              <span className={`text-[10.5px] font-medium px-2 py-0.5 rounded-full ${po.status === "Paid" ? "bg-[#16A34A]/10 text-[#16A34A]" : po.status === "Cancelled" ? "bg-[#EF4444]/10 text-[#EF4444]" : "bg-[#F59E0B]/10 text-[#F59E0B]"}`}>{po.status}</span>
            </div>
            <div className="space-y-1 mb-3">
              {po.items.map((it, i) => (
                <div key={i} className="flex items-center justify-between text-[12.5px]">
                  <span className="text-slate-600">{it.name} × {it.qty}</span>
                  <span className="font-mono text-slate-500">TZS {money(it.qty * it.cost)}k</span>
                </div>
              ))}
            </div>
            <div className="flex items-center justify-between pt-3 border-t border-slate-100">
              <span className="text-[11.5px] text-slate-400">Total</span>
              <span className="text-[15px] font-mono font-bold text-[#111827]">TZS {money(Math.round(total))}k</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function SupplierInvoiceUploadTab({ myOrders, filesHook }) {
  const [selectedPO, setSelectedPO] = useState(myOrders[0]?.id || "");
  const [fileName, setFileName] = useState("");
  const [busy, setBusy] = useState(false);
  const uploadedForPO = filesHook.rows.filter((f) => f.linkedRecord === selectedPO && f.folder === "Purchase Orders");

  async function upload(e) {
    e.preventDefault();
    if (!fileName.trim() || !selectedPO) return;
    setBusy(true);
    const draft = {
      id: docId("DOC"), name: fileName.trim(), type: "pdf", folder: "Purchase Orders",
      size: "—", uploadedBy: "Supplier", date: TODAY.toISOString().slice(0, 10), linkedRecord: selectedPO, content: "", versions: [],
    };
    filesHook.setRows((prev) => [draft, ...prev]);
    setFileName("");
    notify(`Invoice submitted for ${selectedPO} — the business will review it.`);
    if (IS_CONFIGURED) {
      try { await sb("documents").insert({ name: draft.name, file_type: draft.type, folder: draft.folder, linked_record: draft.linkedRecord }).run(); } catch (_e) { notify("Submitted locally, but sending to the server failed.", "error"); }
    }
    setBusy(false);
  }

  if (myOrders.length === 0) return <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm"><EmptyState icon={UploadCloud} title="No purchase orders to invoice against" hint="You'll be able to upload an invoice once a purchase order is issued to you." /></div>;

  return (
    <div className="space-y-4">
      <form onSubmit={upload} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5 space-y-3">
        <FormField label="Purchase order">
          <select className={inputClass} value={selectedPO} onChange={(e) => setSelectedPO(e.target.value)}>
            {myOrders.map((po) => <option key={po.id} value={po.id}>{po.id}</option>)}
          </select>
        </FormField>
        <FormField label="Invoice file name" required>
          <input className={inputClass} value={fileName} onChange={(e) => setFileName(e.target.value)} placeholder="e.g. Invoice-4471.pdf" />
          <p className="text-[11px] text-slate-400 mt-1">This demo register doesn&apos;t store raw file bytes (see the Document Center&apos;s own note on this) — it records the invoice as a real, trackable entry the business can see and act on.</p>
        </FormField>
        <button type="submit" disabled={busy || !fileName.trim()} className="btn-primary text-white text-[12.5px] font-medium rounded-lg py-2.5 w-full disabled:opacity-40">Submit Invoice</button>
      </form>
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm">
        {uploadedForPO.length === 0 ? (
          <EmptyState icon={FileText} title="No invoices submitted for this PO yet" hint="Invoices you submit for the selected purchase order will appear here." />
        ) : (
          <div className="divide-y divide-slate-50">
            {uploadedForPO.map((f) => (
              <div key={f.id} className="flex items-center gap-2.5 px-4 py-3">
                <FileText size={16} className="text-[#EF4444] shrink-0" />
                <div className="min-w-0 flex-1"><p className="text-[12.5px] font-medium text-[#111827] truncate">{f.name}</p><p className="text-[11px] text-slate-400">Submitted {f.date}</p></div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function SupplierPaymentsTab({ myPayments }) {
  const totalPaid = myPayments.filter((e) => e.status === "Paid").reduce((s, e) => s + e.amount, 0);
  const totalPending = myPayments.filter((e) => e.status !== "Paid").reduce((s, e) => s + e.amount, 0);
  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4"><p className="text-[11px] text-slate-400 mb-1">Received to date</p><p className="text-[17px] font-mono font-bold text-[#16A34A]">TZS {money(Math.round(totalPaid))}k</p></div>
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4"><p className="text-[11px] text-slate-400 mb-1">Pending</p><p className="text-[17px] font-mono font-bold text-[#F59E0B]">TZS {money(Math.round(totalPending))}k</p></div>
      </div>
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm">
        {myPayments.length === 0 ? (
          <EmptyState icon={Wallet} title="No payment history yet" hint="Payments made to you will appear here." />
        ) : (
          <div className="divide-y divide-slate-50">
            {myPayments.map((e) => (
              <div key={e.id} className="flex items-center justify-between px-4 py-3">
                <div><p className="text-[12.5px] font-medium text-[#111827]">{e.category}</p><p className="text-[11px] text-slate-400">{e.date}{e.method ? ` · ${e.method}` : ""}</p></div>
                <div className="text-right">
                  <p className="text-[13px] font-mono font-semibold text-[#111827]">TZS {money(Math.round(e.amount))}k</p>
                  <span className={`text-[10px] font-medium ${e.status === "Paid" ? "text-[#16A34A]" : "text-[#F59E0B]"}`}>{e.status}</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function SupplierContractsTab({ myContracts }) {
  return (
    <div className="space-y-3">
      {myContracts.length === 0 && <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm"><EmptyState icon={FileCheck} title="No contracts on file" hint="Supply agreements with your company will appear here." /></div>}
      {myContracts.map((c) => (
        <div key={c.id} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5">
          <div className="flex items-start justify-between mb-2">
            <div><p className="text-[13.5px] font-semibold text-[#111827]">{c.id}</p><p className="text-[11px] text-slate-400">{c.type}</p></div>
            <p className="text-[15px] font-mono font-bold text-[#111827]">TZS {money(Math.round(c.value))}k</p>
          </div>
          <p className="text-[11.5px] text-slate-500 mb-2">{c.startDate} — {c.endDate || "Open-ended"}</p>
          {c.notes && <p className="text-[12.5px] text-slate-600 leading-relaxed">{c.notes}</p>}
        </div>
      ))}
    </div>
  );
}

function SupplierDeliveriesTab({ myOrders, purchaseOrdersHook }) {
  const [editingId, setEditingId] = useState(null);
  const [newDate, setNewDate] = useState("");
  const pending = myOrders.filter((po) => po.status !== "Cancelled" && po.status !== "Paid");

  // Calls the real supplier_update_delivery_date RPC (schema section
  // "SUPPLIER PORTAL") rather than an UPDATE straight to the table — RLS
  // alone can't stop a supplier with row UPDATE access from also rewriting
  // their PO's status, so the RPC is the only door, and it only ever
  // touches expected_date after verifying the PO is genuinely theirs.
  async function saveDate(po) {
    if (!newDate) return;
    if (IS_CONFIGURED) {
      try {
        await callRpc("supplier_update_delivery_date", { p_po_doc_number: po.id, p_new_expected_date: newDate }, (typeof window !== "undefined" && window.localStorage.getItem("bs_access_token")) || "");
      } catch (_e) { notify("Couldn't update the delivery date on the server.", "error"); }
    }
    purchaseOrdersHook.setRows((prev) => prev.map((p) => (p.id === po.id ? { ...p, expectedDate: newDate } : p)));
    notify(`Delivery date updated for ${po.id}`);
    setEditingId(null);
  }

  return (
    <div className="space-y-3">
      {pending.length === 0 && <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm"><EmptyState icon={Truck} title="No active deliveries" hint="Purchase orders awaiting delivery will appear here." /></div>}
      {pending.map((po) => (
        <div key={po.id} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 sm:p-5">
          <div className="flex items-center justify-between mb-2">
            <p className="text-[13.5px] font-semibold text-[#111827]">{po.id}</p>
            <span className="text-[10.5px] font-medium px-2 py-0.5 rounded-full bg-[#F59E0B]/10 text-[#F59E0B]">{po.status}</span>
          </div>
          <p className="text-[12px] text-slate-500 mb-3">Currently committed: {po.expectedDate || "No date set"}</p>
          {editingId === po.id ? (
            <div className="flex gap-2">
              <input type="date" value={newDate} onChange={(e) => setNewDate(e.target.value)} className={inputClass} />
              <button onClick={() => saveDate(po)} className="btn-primary text-white text-[12px] font-medium px-3 rounded-lg shrink-0">Save</button>
              <button onClick={() => setEditingId(null)} className="text-[12px] font-medium border border-slate-200 rounded-lg px-3 shrink-0">Cancel</button>
            </div>
          ) : (
            <button onClick={() => { setEditingId(po.id); setNewDate(po.expectedDate || ""); }} className="btn-secondary text-[12px] font-medium rounded-lg py-2 px-3 flex items-center gap-1.5">
              <Truck size={13} /> Update Delivery Date
            </button>
          )}
        </div>
      ))}
    </div>
  );
}

function ComingSoon({ label }) {
  return (
    <div className="h-[70vh] flex flex-col items-center justify-center text-center">
      <div className="w-12 h-12 rounded-xl bg-[#111827]/5 flex items-center justify-center mb-4">
        <Lock size={18} className="text-[#111827]/40" />
      </div>
      <h2 className="text-[16px] font-semibold text-[#111827]">{label} module</h2>
      <p className="text-[13px] text-slate-500 mt-1.5 max-w-xs">
        Next up in the build sequence. Dashboard and CRM are live — this module follows the same architecture.
      </p>
    </div>
  );
}

